`default_nettype none
`include "../accelerator/qnn_model_config.vh"

// =============================================================================
// Module      : de10_lite_top
// Chức năng   : Top-level vật lý cho Terasic DE10-Lite (MAX 10 10M50).
//
// Kết nối mặc định:
//   - MAX10_CLK1_50: clock hệ thống 50 MHz.
//   - KEY[0]: reset nhấn mức thấp, assert nhanh và nhả đồng bộ qua 3 FF.
//   - SW: GPIO input; LEDR[7:0]: GPIO output; LEDR[8]: QNN busy;
//     LEDR[9]: trap/halt để chẩn đoán tại bàn thử.
//   - GPIO[0]: I2C SCL, GPIO[1]: I2C SDA (open-drain, cần pull-up ngoài).
//   - UART_TX được gán vào chân vật lý GPIO header số 2 (PIN_V9) trong QSF.
// =============================================================================
module de10_lite_top (
    input  wire        MAX10_CLK1_50,
    input  wire [1:0]  KEY,
    input  wire [9:0]  SW,
    output wire [9:0]  LEDR,
    inout  wire [1:0]  GPIO,
    output wire        UART_TX
);

    reg [2:0] reset_sync_q;
    reg [9:0] switch_meta_q;
    reg [9:0] switch_sync_q;
    reg [1:0] i2c_meta_q;
    reg [1:0] i2c_sync_q;
    wire rst = reset_sync_q[2];
    wire [9:0] soc_leds;
    wire uart_tx;
    wire i2c_scl_low;
    wire i2c_sda_low;
    wire trap_valid;
    wire qnn_busy;

    always @(posedge MAX10_CLK1_50 or negedge KEY[0]) begin
        if (!KEY[0])
            reset_sync_q <= 3'b111;
        else
            reset_sync_q <= {reset_sync_q[1:0], 1'b0};
    end

    // SW và hai đường I2C không đồng bộ với clock hệ thống. Hai FF đầu vào giảm
    // xác suất metastability lan vào bus fabric/FSM; I2C 100 kHz dư ngân sách
    // cho độ trễ hai chu kỳ 50 MHz.
    always @(posedge MAX10_CLK1_50) begin
        if (rst) begin
            switch_meta_q <= 10'd0;
            switch_sync_q <= 10'd0;
            i2c_meta_q    <= 2'b11;
            i2c_sync_q    <= 2'b11;
        end
        else begin
            switch_meta_q <= SW;
            switch_sync_q <= switch_meta_q;
            i2c_meta_q    <= GPIO;
            i2c_sync_q    <= i2c_meta_q;
        end
    end

    assign GPIO[0] = i2c_scl_low ? 1'b0 : 1'bz;
    assign GPIO[1] = i2c_sda_low ? 1'b0 : 1'bz;
    assign UART_TX = uart_tx;
    assign LEDR[7:0] = soc_leds[7:0];
    assign LEDR[8]   = qnn_busy;
    assign LEDR[9]   = trap_valid;

    rv32_soc #(
        .CLOCK_HZ(50000000),
        .USE_ROM_INIT_FILE(1),
        .ROM_INIT_FILE("../firmware/build/boot.mif"),
        .USE_QNN_INIT_FILES(1),
        .QNN_L1_SHIFT(`QNN_MODEL_L1_SHIFT),
        .QNN_L2_SHIFT(`QNN_MODEL_L2_SHIFT),
        .QNN_OUT_SHIFT(`QNN_MODEL_OUT_SHIFT),
        .QNN_L1_WEIGHT_FILE("../firmware/model/l1_weights.mif"),
        .QNN_L1_BIAS_FILE("../firmware/model/l1_biases.hex"),
        .QNN_L2_WEIGHT_FILE("../firmware/model/l2_weights.mif"),
        .QNN_L2_BIAS_FILE("../firmware/model/l2_biases.hex"),
        .QNN_OUT_WEIGHT_FILE("../firmware/model/out_weights.hex"),
        .QNN_OUT_BIAS_FILE("../firmware/model/out_bias.hex")
    ) u_soc (
        .clk_i(MAX10_CLK1_50), .rst_i(rst), .switches_i(switch_sync_q), .leds_o(soc_leds),
        .uart_tx_o(uart_tx), .i2c_scl_i(i2c_sync_q[0]), .i2c_sda_i(i2c_sync_q[1]),
        .i2c_scl_drive_low_o(i2c_scl_low), .i2c_sda_drive_low_o(i2c_sda_low),
        .halted_o(), .trap_valid_o(trap_valid), .trap_cause_o(), .trap_pc_o(),
        .qnn_busy_o(qnn_busy), .qnn_done_o(), .qnn_result_o()
    );

endmodule

`default_nettype wire

rtl\\bus\\soc_bus.v:
`default_nettype none

`include "soc_map.vh"

// Single-master, 32-bit word bus. No queue: master holds the complete request
// until req && ready at a rising edge. Errors terminate with ready && err.
// Slave lanes: 0 ROM, 1 RAM, 2 GPIO, 3 UART, 4 I2C, 5 extension/QNN, 6 timer.
// Address/data/write strobes are broadcast by the integration layer; only the
// selected slave receives req. Reserved addresses never alias a register.
module soc_bus #(
    parameter integer ROM_WORDS = 8192,
    parameter integer RAM_WORDS = 2048
) (
    // Master request. Address is a byte address aligned to a 32-bit word.
    input  wire         rst_i,
    input  wire         req_i,
    input  wire         we_i,
    input  wire [31:0]  addr_i,
    // Master response. ready && err terminates a failed transaction.
    output reg  [31:0]  rdata_o,
    output reg          ready_o,
    output reg          err_o,
    // Packed slave lanes, indexed by SOC_SLAVE_* from soc_map.vh.
    output reg  [`SOC_SLAVE_COUNT-1:0]    slave_req_o,
    input  wire [`SOC_SLAVE_COUNT*32-1:0] slave_rdata_i,
    input  wire [`SOC_SLAVE_COUNT-1:0]    slave_ready_i,
    input  wire [`SOC_SLAVE_COUNT-1:0]    slave_err_i
);
    localparam [31:0] ROM_BYTES = ROM_WORDS * 4;
    localparam [31:0] RAM_BYTES = RAM_WORDS * 4;
    integer selected;

    always @* begin
        selected = -1;
        rdata_o = 32'd0;
        ready_o = 1'b0;
        err_o = 1'b0;
        slave_req_o = {`SOC_SLAVE_COUNT{1'b0}};
        if (req_i && !rst_i) begin
            if (addr_i[1:0] == 2'b00) begin
                if (addr_i < ROM_BYTES && !we_i)
                    selected = `SOC_SLAVE_ROM;
                else if (addr_i >= `SOC_RAM_BASE &&
                         (addr_i - `SOC_RAM_BASE) < RAM_BYTES)
                    selected = `SOC_SLAVE_RAM;
                else if ((addr_i & `SOC_MMIO_MASK) == `SOC_GPIO_BASE)
                    selected = `SOC_SLAVE_GPIO;
                else if ((addr_i & `SOC_MMIO_MASK) == `SOC_UART_BASE)
                    selected = `SOC_SLAVE_UART;
                else if ((addr_i & `SOC_MMIO_MASK) == `SOC_I2C_BASE)
                    selected = `SOC_SLAVE_I2C;
                else if ((addr_i & `SOC_QNN_MASK) == `SOC_QNN_BASE)
                    selected = `SOC_SLAVE_QNN;
                else if ((addr_i & `SOC_MMIO_MASK) == `SOC_TIMER_BASE)
                    selected = `SOC_SLAVE_TIMER;
            end
            if (selected < 0) begin
                ready_o = 1'b1;
                err_o = 1'b1;
            end
            else begin
                slave_req_o[selected] = 1'b1;
                ready_o = slave_ready_i[selected];
                err_o = slave_ready_i[selected] && slave_err_i[selected];
                if (slave_ready_i[selected] && !slave_err_i[selected])
                    rdata_o = slave_rdata_i[selected*32 +: 32];
            end
        end
    end
endmodule

`default_nettype wire

rtl\\core\\common\\rv32_lsu.v:
`default_nettype none

/*
 * Load/Store Unit (LSU) tổ hợp cho RV32I, bus dữ liệu rộng 32 bit
 *
 * Đặc tả giao tiếp:
 * - addr_i là địa chỉ byte hiệu dụng do ALU tính (rs1 + immediate).
 * - funct3_i dùng mã ISA chuẩn. Load: 000 LB, 001 LH, 010 LW,
 *   100 LBU, 101 LHU. Store: 000 SB, 001 SH, 010 SW.
 * - load_en_i và store_en_i phải loại trừ nhau đối với một lệnh hợp lệ.
 * - load_data_i là word 32 bit đọc tại địa chỉ đã căn word; byte ở địa
 *   chỉ thấp nhất nằm trong load_data_i[7:0] (little-endian).
 * - store_data_i chứa dữ liệu rs2; LSU chỉ dùng 8/16/32 bit thấp tùy cỡ.
 * - mem_addr_o luôn là địa chỉ word đã căn: {addr_i[31:2], 2'b00}.
 * - mem_wdata_o đặt dữ liệu store đúng byte lane; mem_wstrb_o[n] cho phép
 *   ghi byte mem_wdata_o[8*n +: 8].
 * - load_data_o là dữ liệu đã chọn lane và mở rộng dấu/zero lên 32 bit.
 *
 * Thời gian:
 * - Khối hoàn toàn tổ hợp, không phát request/ready và không giữ trạng thái.
 * - Trong pipeline 5 tầng, tín hiệu điều khiển/địa chỉ/store-data đi qua
 *   EX/MEM; dữ liệu đọc ở MEM được khối này căn lane trước khi về MEM/WB.
 * - Khối điều khiển bus bên ngoài chỉ được ghi khi mem_wstrb_o khác 0.
 *
 * Quy tắc an toàn và góc biên:
 * - Byte không có yêu cầu căn hàng. Halfword cần addr_i[0] = 0; word cần
 *   addr_i[1:0] = 00. Truy cập lệch hàng đặt misaligned_o = 1.
 * - Store lệch hàng bị chặn bằng mem_wstrb_o = 0000; load lệch hàng trả 0.
 * - funct3 dành riêng không tạo strobe, không báo lệch hàng và trả load = 0.
 * - LSU không tách một truy cập lệch hàng thành hai giao dịch bus.
 */
module rv32_lsu (
    input  wire [31:0] addr_i,
    input  wire [2:0]  funct3_i,
    input  wire        load_en_i,
    input  wire        store_en_i,
    input  wire [31:0] store_data_i,
    input  wire [31:0] load_data_i,

    output wire [31:0] mem_addr_o,
    output reg  [31:0] mem_wdata_o,
    output reg  [3:0]  mem_wstrb_o,
    output reg  [31:0] load_data_o,
    output reg         misaligned_o
);

    localparam [2:0]
        F3_BYTE   = 3'b000,
        F3_HALF   = 3'b001,
        F3_WORD   = 3'b010,
        F3_BYTE_U = 3'b100,
        F3_HALF_U = 3'b101;

    wire [4:0] lane_shift;
    reg  [31:0] load_shifted;

    assign mem_addr_o = {addr_i[31:2], 2'b00};
    assign lane_shift = {addr_i[1:0], 3'b000};

    always @(*) begin
        mem_wdata_o  = 32'b0;
        mem_wstrb_o  = 4'b0000;
        load_data_o  = 32'b0;
        misaligned_o = 1'b0;
        load_shifted = load_data_i >> lane_shift;

        if (load_en_i) begin
            case (funct3_i)
                F3_BYTE: begin
                    load_data_o = {
                        {24{load_shifted[7]}},
                        load_shifted[7:0]
                    };
                end

                F3_HALF: begin
                    if (addr_i[0]) begin
                        misaligned_o = 1'b1;
                        load_data_o  = 32'b0;
                    end
                    else begin
                        load_data_o = {
                            {16{load_shifted[15]}},
                            load_shifted[15:0]
                        };
                    end
                end

                F3_WORD: begin
                    if (addr_i[1:0] != 2'b00) begin
                        misaligned_o = 1'b1;
                        load_data_o  = 32'b0;
                    end
                    else begin
                        load_data_o = load_data_i;
                    end
                end

                F3_BYTE_U: begin
                    load_data_o = {24'b0, load_shifted[7:0]};
                end

                F3_HALF_U: begin
                    if (addr_i[0]) begin
                        misaligned_o = 1'b1;
                        load_data_o  = 32'b0;
                    end
                    else begin
                        load_data_o = {16'b0, load_shifted[15:0]};
                    end
                end

                default: load_data_o = 32'b0;
            endcase
        end

        if (store_en_i) begin
            case (funct3_i)
                F3_BYTE: begin
                    mem_wstrb_o = 4'b0001 << addr_i[1:0];
                    mem_wdata_o =
                        {24'b0, store_data_i[7:0]} << lane_shift;
                end

                F3_HALF: begin
                    if (addr_i[0]) begin
                        misaligned_o = 1'b1;
                        mem_wstrb_o  = 4'b0000;
                        mem_wdata_o  = 32'b0;
                    end
                    else begin
                        mem_wstrb_o = 4'b0011 << addr_i[1:0];
                        mem_wdata_o =
                            {16'b0, store_data_i[15:0]} << lane_shift;
                    end
                end

                F3_WORD: begin
                    if (addr_i[1:0] != 2'b00) begin
                        misaligned_o = 1'b1;
                        mem_wstrb_o  = 4'b0000;
                        mem_wdata_o  = 32'b0;
                    end
                    else begin
                        mem_wstrb_o = 4'b1111;
                        mem_wdata_o = store_data_i;
                    end
                end

                default: begin
                    mem_wstrb_o = 4'b0000;
                    mem_wdata_o = 32'b0;
                end
            endcase
        end
    end

endmodule

`default_nettype wire

rtl\\core\\control\\rv32_hazard_unit.v:
`default_nettype none
`include "rv32_defs.vh"

// =============================================================================
// Module      : rv32_hazard_unit
// Chức năng   : Phát hiện hazard dữ liệu và chọn đường forwarding cho pipeline
//               RV32I 5 tầng IF/ID/EX/MEM/WB.
// Kiểu mạch   : Logic tổ hợp, không có trạng thái và không có độ trễ chu kỳ.
//
// Đặc tả giao tiếp:
//   - Nhóm id_* mô tả lệnh đang ở tầng ID. Hai cờ id_uses_rs* ngăn stall
//     giả đối với các trường bit có hình dạng giống rs1/rs2 nhưng lệnh không dùng.
//   - Nhóm ex_* dùng để phát hiện load-use. Kết quả load chưa sẵn sàng cho lệnh
//     ngay sau nó, vì vậy pipeline phải chèn đúng một bubble rồi chờ thêm nếu
//     tầng MEM bị wait-state.
//   - Nhóm mem_*/wb_* dùng để forward toán hạng cho lệnh đang ở tầng EX.
//   - Dữ liệu từ MEM có ưu tiên cao hơn WB vì đó là giá trị mới hơn. Load tại
//     MEM không được chọn: dữ liệu chỉ được chốt và forward từ WB.
//
// Mã forward:
//   2'b00: dùng dữ liệu đã chốt trong ID/EX.
//   2'b01: dùng dữ liệu write-back tại MEM/WB.
//   2'b10: dùng kết quả sớm tại EX/MEM.
//   2'b11: dự phòng, module không phát mã này.
//
// Bất biến:
//   - x0 không tạo hazard và không bao giờ là nguồn forwarding.
//   - Mọi output luôn có giá trị xác định, kể cả khi các stage không valid.
// =============================================================================
module rv32_hazard_unit (
    input  wire [4:0] id_rs1_addr_i,
    input  wire [4:0] id_rs2_addr_i,
    input  wire       id_uses_rs1_i,
    input  wire       id_uses_rs2_i,

    input  wire       ex_valid_i,
    input  wire       ex_load_i,
    input  wire [4:0] ex_rd_addr_i,
    input  wire [4:0] ex_rs1_addr_i,
    input  wire [4:0] ex_rs2_addr_i,

    input  wire       mem_valid_i,
    input  wire       mem_reg_write_i,
    input  wire       mem_load_i,
    input  wire [4:0] mem_rd_addr_i,

    input  wire       wb_valid_i,
    input  wire       wb_reg_write_i,
    input  wire [4:0] wb_rd_addr_i,

    output reg        stall_load_use_o,
    output reg  [1:0] forward_rs1_o,
    output reg  [1:0] forward_rs2_o
);

    localparam [1:0]
        FWD_NONE = `RV32_FWD_NONE,
        FWD_WB = `RV32_FWD_WB,
        FWD_MEM = `RV32_FWD_MEM;

    always @(*) begin
        stall_load_use_o = 1'b0;
        forward_rs1_o    = FWD_NONE;
        forward_rs2_o    = FWD_NONE;

        if (ex_valid_i && ex_load_i && (ex_rd_addr_i != 5'd0)) begin
            if ((id_uses_rs1_i && (id_rs1_addr_i == ex_rd_addr_i)) ||
                (id_uses_rs2_i && (id_rs2_addr_i == ex_rd_addr_i))) begin
                stall_load_use_o = 1'b1;
            end
        end

        if (mem_valid_i && mem_reg_write_i && !mem_load_i &&
            (mem_rd_addr_i != 5'd0) &&
            (mem_rd_addr_i == ex_rs1_addr_i)) begin
            forward_rs1_o = FWD_MEM;
        end
        else if (wb_valid_i && wb_reg_write_i &&
                 (wb_rd_addr_i != 5'd0) &&
                 (wb_rd_addr_i == ex_rs1_addr_i)) begin
            forward_rs1_o = FWD_WB;
        end

        if (mem_valid_i && mem_reg_write_i && !mem_load_i &&
            (mem_rd_addr_i != 5'd0) &&
            (mem_rd_addr_i == ex_rs2_addr_i)) begin
            forward_rs2_o = FWD_MEM;
        end
        else if (wb_valid_i && wb_reg_write_i &&
                 (wb_rd_addr_i != 5'd0) &&
                 (wb_rd_addr_i == ex_rs2_addr_i)) begin
            forward_rs2_o = FWD_WB;
        end
    end

endmodule

`default_nettype wire

rtl\\core\\ex\\rv32_alu.v:
`default_nettype none

`include "rv32_defs.vh"

// =============================================================================
// Module      : rv32_alu
// Chức năng   : Khối số học và logic tổ hợp cho datapath RV32I.
//
// Đặc tả giao tiếp
//   - operand_a_i, operand_b_i: hai toán hạng 32 bit.
//   - alu_op_i               : mã phép toán nội bộ, được liệt kê bên dưới.
//   - result_o               : kết quả 32 bit, hợp lệ sau trễ lan truyền tổ hợp.
//
// Nguyên tắc thời gian
//   - Module không có clock và không lưu trạng thái.
//   - Mỗi thay đổi ở đầu vào được phản ánh trực tiếp lên result_o.
//
// Trường hợp biên
//   - ADD/SUB tuân theo số học modulo 2^32; cờ carry/overflow không được xuất.
//   - Các phép dịch chỉ dùng operand_b_i[4:0], đúng quy tắc RV32I.
//   - SRA và SLT diễn giải toán hạng là số bù hai có dấu.
//   - Mã alu_op_i dự phòng luôn trả về 0 để đầu ra xác định và không tạo latch.
// =============================================================================
module rv32_alu (
    input  wire [31:0] operand_a_i,
    input  wire [31:0] operand_b_i,
    input  wire [3:0]  alu_op_i,

    output reg  [31:0] result_o
);

    wire [4:0] shift_amount;

    assign shift_amount = operand_b_i[4:0];

    always @(*) begin
        // Giá trị mặc định bảo đảm logic tổ hợp đầy đủ cho mọi mã điều khiển.
        result_o = 32'b0;

        case (alu_op_i)
            `RV32_ALU_ADD: begin
                result_o = operand_a_i + operand_b_i;
            end

            `RV32_ALU_SUB: begin
                result_o = operand_a_i - operand_b_i;
            end

            `RV32_ALU_AND: begin
                result_o = operand_a_i & operand_b_i;
            end

            `RV32_ALU_OR: begin
                result_o = operand_a_i | operand_b_i;
            end

            `RV32_ALU_XOR: begin
                result_o = operand_a_i ^ operand_b_i;
            end

            `RV32_ALU_SLL: begin
                result_o = operand_a_i << shift_amount;
            end

            `RV32_ALU_SRL: begin
                result_o = operand_a_i >> shift_amount;
            end

            `RV32_ALU_SRA: begin
                result_o = $signed(operand_a_i) >>> shift_amount;
            end

            `RV32_ALU_SLT: begin
                result_o = ($signed(operand_a_i) < $signed(operand_b_i))
                         ? 32'd1
                         : 32'd0;
            end

            `RV32_ALU_SLTU: begin
                result_o = (operand_a_i < operand_b_i) ? 32'd1 : 32'd0;
            end

            `RV32_ALU_COPY_B: begin
                result_o = operand_b_i;
            end

            default: begin
                result_o = 32'b0;
            end
        endcase
    end

endmodule

`default_nettype wire

rtl\\core\\ex\\rv32_ex_stage.v:
`default_nettype none
`include "rv32_defs.vh"

// EX: forwarding toán hạng, ALU/nhánh và kiểm tra địa chỉ lệch hàng.
// Logic tổ hợp, không giữ trạng thái. fault_raw được khóa bởi valid/exc_valid;
// bộ điều khiển core phân xử lỗi và redirect theo tuổi lệnh trước khi áp dụng.
// Chi tiết ranh giới pipeline: docs/giao_tiep_rtl_vi.md, mục 5.
module rv32_ex_stage (
    input  wire         valid_i,
    input  wire         exc_valid_i,
    input  wire [31:0]  rs1_data_i,
    input  wire [31:0]  rs2_data_i,
    input  wire [1:0]   op_a_sel_i,
    input  wire         op_b_imm_i,
    input  wire [31:0]  pc_i,
    input  wire [31:0]  imm_i,
    input  wire [3:0]   alu_op_i,
    input  wire         branch_i,
    input  wire [2:0]   funct3_i,
    input  wire         jal_i,
    input  wire         jalr_i,
    input  wire         load_i,
    input  wire         store_i,
    input  wire [1:0]   exmem_wb_sel_i,
    input  wire [31:0]  exmem_pc4_i,
    input  wire [31:0]  exmem_alu_result_i,
    input  wire [31:0]  memwb_wb_data_i,
    input  wire [1:0]   forward_rs1_sel_i,
    input  wire [1:0]   forward_rs2_sel_i,
    output reg  [31:0]  rs1_value_o,
    output reg  [31:0]  rs2_value_o,
    output wire [31:0]  alu_result_o,
    output wire [31:0]  control_target_o,
    output wire         control_taken_o,
    output wire         target_misaligned_o,
    output wire         fault_raw_o,
    output reg  [4:0]   fault_cause_o
);
    localparam [1:0] OP_A_PC = `RV32_OP_A_PC;
    localparam [1:0] OP_A_ZERO = `RV32_OP_A_ZERO;
    localparam [1:0] WB_PC4 = `RV32_WB_PC4;
    localparam [1:0] FWD_WB = `RV32_FWD_WB;
    localparam [1:0] FWD_MEM = `RV32_FWD_MEM;
    localparam [4:0] CAUSE_INSTR_ADDR_MISALIGNED = `RV32_CAUSE_INSTR_ADDR_MISALIGNED;
    localparam [4:0] CAUSE_LOAD_ADDR_MISALIGNED = `RV32_CAUSE_LOAD_ADDR_MISALIGNED;
    localparam [4:0] CAUSE_STORE_ADDR_MISALIGNED = `RV32_CAUSE_STORE_ADDR_MISALIGNED;

    wire [31:0] mem_forward_data;
    assign mem_forward_data = (exmem_wb_sel_i == WB_PC4)
                            ? exmem_pc4_i
                            : exmem_alu_result_i;

    always @(*) begin
        case (forward_rs1_sel_i)
            FWD_MEM: rs1_value_o = mem_forward_data;
            FWD_WB : rs1_value_o = memwb_wb_data_i;
            default: rs1_value_o = rs1_data_i;
        endcase

        case (forward_rs2_sel_i)
            FWD_MEM: rs2_value_o = mem_forward_data;
            FWD_WB : rs2_value_o = memwb_wb_data_i;
            default: rs2_value_o = rs2_data_i;
        endcase
    end

    // -------------------------------------------------------------------------
    // EX: ALU, branch/jump target và kiểm tra alignment.
    // -------------------------------------------------------------------------
    reg [31:0] ex_operand_a;
    wire [31:0] ex_operand_b;

    always @(*) begin
        case (op_a_sel_i)
            OP_A_PC  : ex_operand_a = pc_i;
            OP_A_ZERO: ex_operand_a = 32'b0;
            default  : ex_operand_a = rs1_value_o;
        endcase
    end
    assign ex_operand_b = op_b_imm_i ? imm_i : rs2_value_o;

    rv32_alu u_alu (
        .operand_a_i (ex_operand_a),
        .operand_b_i (ex_operand_b),
        .alu_op_i    (alu_op_i),
        .result_o    (alu_result_o)
    );

    wire ex_branch_taken;
    rv32_branch_unit u_branch_unit (
        .branch_en_i    (branch_i && valid_i &&
                         !exc_valid_i),
        .funct3_i       (funct3_i),
        .rs1_data_i     (rs1_value_o),
        .rs2_data_i     (rs2_value_o),
        .branch_taken_o (ex_branch_taken)
    );

    // Decoder chọn PC/rs1 cộng immediate cho branch, JAL và JALR.
    // Tái sử dụng bộ cộng ALU làm đích; JALR xóa bit 0 trước kiểm tra căn chỉnh.
    assign control_target_o = jalr_i
                             ? {alu_result_o[31:1], 1'b0}
                             : alu_result_o;
    assign control_taken_o = jal_i || jalr_i ||
                              (branch_i && ex_branch_taken);
    assign target_misaligned_o = control_taken_o &&
                                  (control_target_o[1:0] != 2'b00);

    wire [31:0] ex_lsu_addr_unused;
    wire [31:0] ex_lsu_wdata_unused;
    wire [3:0]  ex_lsu_wstrb_unused;
    wire [31:0] ex_lsu_load_unused;
    wire        ex_lsu_misaligned;

    rv32_lsu u_lsu_ex_check (
        .addr_i         (alu_result_o),
        .funct3_i       (funct3_i),
        .load_en_i      (load_i && valid_i &&
                         !exc_valid_i),
        .store_en_i     (store_i && valid_i &&
                         !exc_valid_i),
        .store_data_i   (rs2_value_o),
        .load_data_i    (32'b0),
        .mem_addr_o     (ex_lsu_addr_unused),
        .mem_wdata_o    (ex_lsu_wdata_unused),
        .mem_wstrb_o    (ex_lsu_wstrb_unused),
        .load_data_o    (ex_lsu_load_unused),
        .misaligned_o   (ex_lsu_misaligned)
    );

    assign fault_raw_o = valid_i && !exc_valid_i &&
                          (target_misaligned_o || ex_lsu_misaligned);

    always @(*) begin
        if (target_misaligned_o)
            fault_cause_o = CAUSE_INSTR_ADDR_MISALIGNED;
        else if (load_i)
            fault_cause_o = CAUSE_LOAD_ADDR_MISALIGNED;
        else
            fault_cause_o = CAUSE_STORE_ADDR_MISALIGNED;
    end

endmodule

`default_nettype wire

rtl\\core\\id\\rv32_decoder.v:
`default_nettype none

`include "rv32_defs.vh"

`default_nettype none

// =============================================================================
// Module    : rv32_decoder
// Chức năng : Giải mã nghiêm ngặt tập lệnh cơ sở RV32I v2.1.
//
// Đặc tả hoạt động:
//   - Logic tổ hợp, không có clock, độ trễ một tầng logic giải mã.
//   - Mọi lệnh không hợp lệ đều đặt illegal_o=1 và vô hiệu toàn bộ
//     tác dụng phụ như ghi thanh ghi, load, store hay thay đổi luồng điều khiển.
//   - branch_o chỉ xác nhận sáu lệnh nhánh chuẩn. Khối branch phía sau
//     dùng instr_i[14:12] để chọn điều kiện so sánh.
//   - load_o/store_o chỉ xác nhận các kích thước hợp lệ. Khối LSU dùng
//     instr_i[14:12] để chọn byte/half-word/word và signed/unsigned.
//   - FENCE (funct3=000) là lệnh hợp lệ; các trường dự trữ rs1/rd/fm
//     không được kiểm tra. FENCE.I và Zicsr không thuộc baseline này.
//   - ECALL và EBREAK phải khớp chính xác toàn bộ mã lệnh.
//   - uses_rs1_o/uses_rs2_o mô tả phụ thuộc dữ liệu thực sự cho
//     hazard/forwarding unit của pipeline; lệnh illegal không dùng nguồn nào.
//
// Quy ước datapath:
//   - op_b_imm_o=1: toán hạng B lấy từ immediate; =0: lấy từ rs2.
//   - Nhánh/JAL tính đích bằng PC + immediate; JALR tính rs1 + immediate.
//   - reg_write_o chỉ là yêu cầu ghi; register file vẫn phải chặn rd=x0.
// =============================================================================

module rv32_decoder (
    input  wire [31:0] instr_i,

    output reg  [3:0]  alu_op_o,
    output reg  [2:0]  imm_type_o,
    output reg  [1:0]  op_a_sel_o,
    output reg         op_b_imm_o,
    output reg         reg_write_o,
    output reg  [1:0]  wb_sel_o,
    output reg         branch_o,
    output reg         jal_o,
    output reg         jalr_o,
    output reg         load_o,
    output reg         store_o,
    output reg         fence_o,
    output reg         ecall_o,
    output reg         ebreak_o,
    output reg         illegal_o,
    output reg         uses_rs1_o,
    output reg         uses_rs2_o
);

    wire [6:0] opcode;
    wire [2:0] funct3;
    wire [6:0] funct7;

    assign opcode = instr_i[6:0];
    assign funct3 = instr_i[14:12];
    assign funct7 = instr_i[31:25];

    always @(*) begin
        // Giá trị an toàn: lệnh chưa được công nhận là illegal và
        // không được phép gây bất kỳ thay đổi trạng thái kiến trúc nào.
        alu_op_o    = `RV32_ALU_ADD;
        imm_type_o  = `RV32_IMM_NONE;
        op_a_sel_o  = `RV32_OP_A_RS1;
        op_b_imm_o  = 1'b0;
        reg_write_o = 1'b0;
        wb_sel_o    = `RV32_WB_ALU;
        branch_o    = 1'b0;
        jal_o       = 1'b0;
        jalr_o      = 1'b0;
        load_o      = 1'b0;
        store_o     = 1'b0;
        fence_o     = 1'b0;
        ecall_o     = 1'b0;
        ebreak_o    = 1'b0;
        illegal_o   = 1'b1;
        uses_rs1_o  = 1'b0;
        uses_rs2_o  = 1'b0;

        case (opcode)
            `RV32_OPCODE_LUI: begin
                alu_op_o    = `RV32_ALU_COPY_B;
                imm_type_o  = `RV32_IMM_U;
                op_a_sel_o  = `RV32_OP_A_ZERO;
                op_b_imm_o  = 1'b1;
                reg_write_o = 1'b1;
                illegal_o   = 1'b0;
            end

            `RV32_OPCODE_AUIPC: begin
                alu_op_o    = `RV32_ALU_ADD;
                imm_type_o  = `RV32_IMM_U;
                op_a_sel_o  = `RV32_OP_A_PC;
                op_b_imm_o  = 1'b1;
                reg_write_o = 1'b1;
                illegal_o   = 1'b0;
            end

            `RV32_OPCODE_JAL: begin
                alu_op_o    = `RV32_ALU_ADD;
                imm_type_o  = `RV32_IMM_J;
                op_a_sel_o  = `RV32_OP_A_PC;
                op_b_imm_o  = 1'b1;
                reg_write_o = 1'b1;
                wb_sel_o    = `RV32_WB_PC4;
                jal_o       = 1'b1;
                illegal_o   = 1'b0;
            end

            `RV32_OPCODE_JALR: begin
                if (funct3 == 3'b000) begin
                    alu_op_o    = `RV32_ALU_ADD;
                    imm_type_o  = `RV32_IMM_I;
                    op_a_sel_o  = `RV32_OP_A_RS1;
                    op_b_imm_o  = 1'b1;
                    reg_write_o = 1'b1;
                    wb_sel_o    = `RV32_WB_PC4;
                    jalr_o      = 1'b1;
                    illegal_o   = 1'b0;
                    uses_rs1_o  = 1'b1;
                end
            end

            `RV32_OPCODE_BRANCH: begin
                case (funct3)
                    3'b000, // BEQ
                    3'b001, // BNE
                    3'b100, // BLT
                    3'b101, // BGE
                    3'b110, // BLTU
                    3'b111: // BGEU
                        illegal_o = 1'b0;
                    default:
                        illegal_o = 1'b1;
                endcase

                if (!illegal_o) begin
                    alu_op_o   = `RV32_ALU_ADD;
                    imm_type_o = `RV32_IMM_B;
                    op_a_sel_o = `RV32_OP_A_PC;
                    op_b_imm_o = 1'b1;
                    branch_o   = 1'b1;
                    uses_rs1_o = 1'b1;
                    uses_rs2_o = 1'b1;
                end
            end

            `RV32_OPCODE_LOAD: begin
                case (funct3)
                    3'b000, // LB
                    3'b001, // LH
                    3'b010, // LW
                    3'b100, // LBU
                    3'b101: // LHU
                        illegal_o = 1'b0;
                    default:
                        illegal_o = 1'b1;
                endcase

                if (!illegal_o) begin
                    alu_op_o    = `RV32_ALU_ADD;
                    imm_type_o  = `RV32_IMM_I;
                    op_a_sel_o  = `RV32_OP_A_RS1;
                    op_b_imm_o  = 1'b1;
                    reg_write_o = 1'b1;
                    wb_sel_o    = `RV32_WB_LOAD;
                    load_o      = 1'b1;
                    uses_rs1_o  = 1'b1;
                end
            end

            `RV32_OPCODE_STORE: begin
                case (funct3)
                    3'b000, // SB
                    3'b001, // SH
                    3'b010: // SW
                        illegal_o = 1'b0;
                    default:
                        illegal_o = 1'b1;
                endcase

                if (!illegal_o) begin
                    alu_op_o   = `RV32_ALU_ADD;
                    imm_type_o = `RV32_IMM_S;
                    op_a_sel_o = `RV32_OP_A_RS1;
                    op_b_imm_o = 1'b1;
                    store_o    = 1'b1;
                    uses_rs1_o = 1'b1;
                    uses_rs2_o = 1'b1;
                end
            end

            `RV32_OPCODE_OP_IMM: begin
                case (funct3)
                    3'b000: begin // ADDI
                        alu_op_o  = `RV32_ALU_ADD;
                        illegal_o = 1'b0;
                    end
                    3'b010: begin // SLTI
                        alu_op_o  = `RV32_ALU_SLT;
                        illegal_o = 1'b0;
                    end
                    3'b011: begin // SLTIU
                        alu_op_o  = `RV32_ALU_SLTU;
                        illegal_o = 1'b0;
                    end
                    3'b100: begin // XORI
                        alu_op_o  = `RV32_ALU_XOR;
                        illegal_o = 1'b0;
                    end
                    3'b110: begin // ORI
                        alu_op_o  = `RV32_ALU_OR;
                        illegal_o = 1'b0;
                    end
                    3'b111: begin // ANDI
                        alu_op_o  = `RV32_ALU_AND;
                        illegal_o = 1'b0;
                    end
                    3'b001: begin // SLLI: imm[11:5] phải bằng 0000000.
                        if (funct7 == 7'b0000000) begin
                            alu_op_o  = `RV32_ALU_SLL;
                            illegal_o = 1'b0;
                        end
                    end
                    3'b101: begin
                        case (funct7)
                            7'b0000000: begin // SRLI
                                alu_op_o  = `RV32_ALU_SRL;
                                illegal_o = 1'b0;
                            end
                            7'b0100000: begin // SRAI
                                alu_op_o  = `RV32_ALU_SRA;
                                illegal_o = 1'b0;
                            end
                            default:
                                illegal_o = 1'b1;
                        endcase
                    end
                    default:
                        illegal_o = 1'b1;
                endcase

                if (!illegal_o) begin
                    imm_type_o  = `RV32_IMM_I;
                    op_a_sel_o  = `RV32_OP_A_RS1;
                    op_b_imm_o  = 1'b1;
                    reg_write_o = 1'b1;
                    uses_rs1_o  = 1'b1;
                end
            end

            `RV32_OPCODE_OP: begin
                case ({funct7, funct3})
                    10'b0000000_000: begin // ADD
                        alu_op_o  = `RV32_ALU_ADD;
                        illegal_o = 1'b0;
                    end
                    10'b0100000_000: begin // SUB
                        alu_op_o  = `RV32_ALU_SUB;
                        illegal_o = 1'b0;
                    end
                    10'b0000000_001: begin // SLL
                        alu_op_o  = `RV32_ALU_SLL;
                        illegal_o = 1'b0;
                    end
                    10'b0000000_010: begin // SLT
                        alu_op_o  = `RV32_ALU_SLT;
                        illegal_o = 1'b0;
                    end
                    10'b0000000_011: begin // SLTU
                        alu_op_o  = `RV32_ALU_SLTU;
                        illegal_o = 1'b0;
                    end
                    10'b0000000_100: begin // XOR
                        alu_op_o  = `RV32_ALU_XOR;
                        illegal_o = 1'b0;
                    end
                    10'b0000000_101: begin // SRL
                        alu_op_o  = `RV32_ALU_SRL;
                        illegal_o = 1'b0;
                    end
                    10'b0100000_101: begin // SRA
                        alu_op_o  = `RV32_ALU_SRA;
                        illegal_o = 1'b0;
                    end
                    10'b0000000_110: begin // OR
                        alu_op_o  = `RV32_ALU_OR;
                        illegal_o = 1'b0;
                    end
                    10'b0000000_111: begin // AND
                        alu_op_o  = `RV32_ALU_AND;
                        illegal_o = 1'b0;
                    end
                    default:
                        illegal_o = 1'b1;
                endcase

                if (!illegal_o) begin
                    op_a_sel_o  = `RV32_OP_A_RS1;
                    reg_write_o = 1'b1;
                    uses_rs1_o  = 1'b1;
                    uses_rs2_o  = 1'b1;
                end
            end

            `RV32_OPCODE_MISC_MEM: begin
                // Chỉ FENCE thuộc baseline RV32I. Theo hợp đồng module,
                // các trường dự trữ của FENCE được bỏ qua.
                if (funct3 == 3'b000) begin
                    fence_o   = 1'b1;
                    illegal_o = 1'b0;
                end
            end

            `RV32_OPCODE_SYSTEM: begin
                if (instr_i == 32'h0000_0073) begin
                    ecall_o   = 1'b1;
                    illegal_o = 1'b0;
                end
                else if (instr_i == 32'h0010_0073) begin
                    ebreak_o  = 1'b1;
                    illegal_o = 1'b0;
                end
                // CSR*, MRET/WFI và SYSTEM dự trữ giữ default illegal.
            end

            default: begin
                illegal_o = 1'b1;
            end
        endcase
    end

endmodule

`default_nettype wire

rtl\\core\\id\\rv32_id_stage.v:
`default_nettype none
`include "rv32_defs.vh"

// ID: giải mã RV32I, tạo immediate và đọc thanh ghi có bypass từ WB.
// Giải mã tổ hợp; register file ghi/reset tại cạnh lên. Payload đầu vào chỉ
// được core sử dụng khi IF/ID hợp lệ; decode_exc không tự tạo tác dụng phụ.
// Chi tiết ranh giới pipeline: docs/giao_tiep_rtl_vi.md, mục 5.
module rv32_id_stage (
    input  wire         clk_i,
    input  wire         rst_i,
    input  wire [31:0]  instr_i,
    input  wire         exc_valid_i,
    input  wire [4:0]   exc_cause_i,
    input  wire         wb_regfile_we_i,
    input  wire [4:0]   memwb_rd_addr_i,
    input  wire [31:0]  memwb_wb_data_i,
    output wire [4:0]   rs1_addr_o,
    output wire [4:0]   rs2_addr_o,
    output wire [4:0]   rd_addr_o,
    output wire [2:0]   funct3_o,
    output wire [31:0]  rs1_data_o,
    output wire [31:0]  rs2_data_o,
    output wire [31:0]  imm_o,
    output wire [3:0]   alu_op_o,
    output wire [1:0]   op_a_sel_o,
    output wire         op_b_imm_o,
    output wire         reg_write_o,
    output wire [1:0]   wb_sel_o,
    output wire         branch_o,
    output wire         jal_o,
    output wire         jalr_o,
    output wire         load_o,
    output wire         store_o,
    output wire         uses_rs1_o,
    output wire         uses_rs2_o,
    output reg          decode_exc_o,
    output wire         any_exc_o,
    output wire [4:0]   any_exc_cause_o
);
    localparam [4:0] CAUSE_ILLEGAL_INSTRUCTION = `RV32_CAUSE_ILLEGAL_INSTRUCTION;
    localparam [4:0] CAUSE_BREAKPOINT = `RV32_CAUSE_BREAKPOINT;
    localparam [4:0] CAUSE_ECALL_MMODE = `RV32_CAUSE_ECALL_MMODE;

    wire [2:0] id_imm_type;

    wire       id_fence;
    wire       id_ecall;
    wire       id_ebreak;
    wire       id_illegal;

    assign rs1_addr_o = instr_i[19:15];
    assign rs2_addr_o = instr_i[24:20];
    assign rd_addr_o  = instr_i[11:7];
    assign funct3_o   = instr_i[14:12];

    rv32_decoder u_decoder (
        .instr_i       (instr_i),
        .alu_op_o      (alu_op_o),
        .imm_type_o    (id_imm_type),
        .op_a_sel_o    (op_a_sel_o),
        .op_b_imm_o    (op_b_imm_o),
        .reg_write_o   (reg_write_o),
        .wb_sel_o      (wb_sel_o),
        .branch_o      (branch_o),
        .jal_o         (jal_o),
        .jalr_o        (jalr_o),
        .load_o        (load_o),
        .store_o       (store_o),
        .fence_o       (id_fence),
        .ecall_o       (id_ecall),
        .ebreak_o      (id_ebreak),
        .illegal_o     (id_illegal),
        .uses_rs1_o    (uses_rs1_o),
        .uses_rs2_o    (uses_rs2_o)
    );

    rv32_imm_gen u_imm_gen (
        .instr_i    (instr_i),
        .imm_type_i (id_imm_type),
        .imm_o      (imm_o)
    );

    rv32_regfile u_regfile (
        .clk_i      (clk_i),
        .rst_i      (rst_i),
        .rs1_addr_i (rs1_addr_o),
        .rs2_addr_i (rs2_addr_o),
        .rs1_data_o (rs1_data_o),
        .rs2_data_o (rs2_data_o),
        .rd_we_i    (wb_regfile_we_i),
        .rd_addr_i  (memwb_rd_addr_i),
        .rd_data_i  (memwb_wb_data_i)
    );

    // Ngoại lệ được phát hiện tại ID. Fetch fault đã có metadata riêng.

    reg [4:0]  id_decode_exc_cause;
    always @(*) begin
        decode_exc_o       = 1'b0;
        id_decode_exc_cause = CAUSE_ILLEGAL_INSTRUCTION;
        if (id_illegal) begin
            decode_exc_o       = 1'b1;
            id_decode_exc_cause = CAUSE_ILLEGAL_INSTRUCTION;
        end
        else if (id_ebreak) begin
            decode_exc_o       = 1'b1;
            id_decode_exc_cause = CAUSE_BREAKPOINT;
        end
        else if (id_ecall) begin
            decode_exc_o       = 1'b1;
            id_decode_exc_cause = CAUSE_ECALL_MMODE;
        end
    end

    assign any_exc_o = exc_valid_i || decode_exc_o;
    assign any_exc_cause_o = exc_valid_i
                            ? exc_cause_i
                            : id_decode_exc_cause;

endmodule

`default_nettype wire

rtl\\core\\id\\rv32_regfile.v:
`default_nettype none

// =============================================================================
// Module      : rv32_regfile
// Chức năng   : Tập 32 thanh ghi nguyên RV32I, hai cổng đọc và một cổng ghi.
//
// Đặc tả giao tiếp
//   - rs1_addr_i/rs2_addr_i chọn hai nguồn đọc tổ hợp độc lập.
//   - rd_we_i, rd_addr_i, rd_data_i tạo cổng ghi đồng bộ ở cạnh lên clk_i.
//   - x0 luôn đọc bằng 0 và mọi yêu cầu ghi x0 đều bị bỏ qua.
//
// Nguyên tắc thời gian cho pipeline 5 tầng
//   - Dữ liệu rd được lưu vào x1..x31 tại cạnh lên khi rd_we_i = 1.
//   - Có bypass write-through WB -> ID: trong chu kỳ ghi, nếu địa chỉ đọc trùng
//     rd_addr_i hợp lệ thì cổng đọc trả ngay rd_data_i, kể cả trước cạnh ghi.
//   - Bypass loại bỏ phụ thuộc WB/ID cùng chu kỳ; các hazard gần hơn vẫn do khối
//     forwarding/stall của pipeline xử lý.
//
// Reset và trường hợp biên
//   - rst_i tích cực mức cao, đồng bộ và ưu tiên hơn thao tác ghi.
//   - Khi rst_i = 1, bypass bị khóa; x1..x31 chỉ được xóa tại cạnh lên kế tiếp.
//   - Thiết kế phải được reset trước khi đọc x1..x31 để tránh trạng thái X.
//   - Reset toàn bộ mảng giúp trạng thái xác định nhưng thường khiến FPGA dùng
//     31 x 32 flip-flop thay vì suy luận block RAM; đây là chủ đích kiến trúc.
// =============================================================================
module rv32_regfile (
    input  wire        clk_i,
    input  wire        rst_i,

    input  wire [4:0]  rs1_addr_i,
    input  wire [4:0]  rs2_addr_i,
    output reg  [31:0] rs1_data_o,
    output reg  [31:0] rs2_data_o,

    input  wire        rd_we_i,
    input  wire [4:0]  rd_addr_i,
    input  wire [31:0] rd_data_i
);

    // x0 là hằng 0 nên chỉ cần phần tử lưu trữ cho x1..x31.
    reg [31:0] registers [1:31];

    wire write_valid;
    integer reset_index;

    assign write_valid = rd_we_i
                       && (rd_addr_i != 5'd0)
                       && !rst_i;

    // Ghi đồng bộ; reset đồng bộ có ưu tiên cao nhất.
    always @(posedge clk_i) begin
        if (rst_i) begin
            for (reset_index = 1; reset_index < 32;
                 reset_index = reset_index + 1) begin
                registers[reset_index] <= 32'b0;
            end
        end
        else if (write_valid) begin
            registers[rd_addr_i] <= rd_data_i;
        end
    end

    // Cổng đọc 1: ưu tiên x0, sau đó bypass WB -> ID, cuối cùng là mảng lưu.
    always @(*) begin
        if (rs1_addr_i == 5'd0) begin
            rs1_data_o = 32'b0;
        end
        else if (write_valid && (rd_addr_i == rs1_addr_i)) begin
            rs1_data_o = rd_data_i;
        end
        else begin
            rs1_data_o = registers[rs1_addr_i];
        end
    end

    // Cổng đọc 2 có cùng chính sách ưu tiên với cổng đọc 1.
    always @(*) begin
        if (rs2_addr_i == 5'd0) begin
            rs2_data_o = 32'b0;
        end
        else if (write_valid && (rd_addr_i == rs2_addr_i)) begin
            rs2_data_o = rd_data_i;
        end
        else begin
            rs2_data_o = registers[rs2_addr_i];
        end
    end

endmodule

`default_nettype wire

rtl\\core\\if\\rv32_if_stage.v:
`default_nettype none
`include "rv32_defs.vh"

// =============================================================================
// Khối lấy lệnh: kênh yêu cầu/đáp ứng độc lập, FIFO hai phần tử.
// Clock: cạnh lên clk_i; reset đồng bộ, tích cực cao.
// Yêu cầu được nhận khi req && gnt; giữ req/addr tới cạnh nhận, kể cả khi flush.
// Mỗi yêu cầu được nhận phải có đúng một đáp ứng, đúng thứ tự, sớm nhất ở cạnh
// kế tiếp. Kênh đáp ứng không có back-pressure; rdata/err chỉ hợp lệ khi rvalid.
// Tổng FIFO + yêu cầu đã nhận + yêu cầu đang giữ không vượt quá hai phần tử.
// ifid_consumed_i xác nhận ID lấy phần tử đầu; bên điều khiển phải chặn tín
// hiệu này khi stall hoặc có sự kiện ưu tiên cao hơn. Flush thắng cập nhật FIFO.
// Cờ kill lưu riêng từng yêu cầu và chỉ xóa khi thay bằng yêu cầu mới, tránh
// khôi phục nhầm yêu cầu cũ khi nhiều sự kiện flush xảy ra liên tiếp.
// Reset phải áp dụng đồng thời cho core và memory, hủy mọi đáp ứng chưa trả.
// Hợp đồng đầy đủ: docs/giao_tiep_rtl_vi.md.
// =============================================================================
module rv32_if_stage #(
    parameter [31:0] RESET_VECTOR = 32'h0000_0000
) (
    input  wire         clk_i,
    input  wire         rst_i,
    input  wire         halted_i,
    input  wire         wb_trap_event_i,
    input  wire         mem_fault_event_i,
    input  wire         ex_fault_event_i,
    input  wire         ex_redirect_event_i,
    input  wire         id_exception_event_i,
    input  wire [31:0]  ex_control_target_i,
    input  wire         ifid_consumed_i,
    input  wire         imem_gnt_i,
    input  wire         imem_rvalid_i,
    input  wire [31:0]  imem_rdata_i,
    input  wire         imem_err_i,
    output wire         imem_req_o,
    output wire [31:0]  imem_addr_o,
    output wire [31:0]  debug_fetch_pc_o,
    output wire         ifid_valid_o,
    output wire [31:0]  ifid_pc_o,
    output wire [31:0]  ifid_instr_o,
    output wire         ifid_exc_valid_o,
    output wire [4:0]   ifid_exc_cause_o
);
    localparam [4:0] CAUSE_INSTR_ADDR_MISALIGNED =
        `RV32_CAUSE_INSTR_ADDR_MISALIGNED;
    localparam [4:0] CAUSE_INSTR_ACCESS_FAULT =
        `RV32_CAUSE_INSTR_ACCESS_FAULT;

    reg         front_stop_q;
    reg  [31:0] fetch_pc_q;

    // Giữ nguyên yêu cầu đã phát trong khi chờ grant.
    reg         req_hold_valid_q;
    reg  [31:0] req_hold_pc_q;
    reg         req_hold_kill_q;

    // Hàng đợi PC và trạng thái hủy, theo thứ tự yêu cầu được nhận.
    reg  [1:0]  req_count_q;
    reg  [31:0] req_pc0_q;
    reg  [31:0] req_pc1_q;
    reg         req_kill0_q;
    reg         req_kill1_q;

    // Phần tử số 0 của FIFO là đầu ra IF/ID.
    reg  [1:0]  fifo_count_q;
    reg  [31:0] fifo_pc0_q;
    reg  [31:0] fifo_pc1_q;
    reg  [31:0] fifo_instr0_q;
    reg  [31:0] fifo_instr1_q;
    reg         fifo_exc0_q;
    reg         fifo_exc1_q;
    reg  [4:0]  fifo_cause0_q;
    reg  [4:0]  fifo_cause1_q;

    wire        external_flush_event;
    wire        stop_event;
    wire        fifo_pop;
    wire [2:0]  frontend_used;
    wire        issue_has_credit;
    wire        new_request_valid;
    wire        request_accept;
    wire        request_capture_hold;
    wire [31:0] request_pc;
    wire        request_kill;
    wire        request_live;
    wire        response_pop;
    wire        response_live;
    wire        response_push;
    wire        local_misaligned_push;
    wire        fifo_push;
    wire [31:0] push_pc;
    wire [31:0] push_instr;
    wire        push_exc;
    wire [4:0]  push_cause;
    wire        fetch_exception_event;

    assign external_flush_event = wb_trap_event_i || halted_i ||
                                  mem_fault_event_i || ex_fault_event_i ||
                                  ex_redirect_event_i ||
                                  id_exception_event_i;
    assign stop_event = wb_trap_event_i || halted_i ||
                        mem_fault_event_i || ex_fault_event_i ||
                        id_exception_event_i;

    assign ifid_valid_o     = (fifo_count_q != 2'd0);
    assign ifid_pc_o        = fifo_pc0_q;
    assign ifid_instr_o     = fifo_instr0_q;
    assign ifid_exc_valid_o = fifo_exc0_q;
    assign ifid_exc_cause_o = fifo_cause0_q;

    assign fifo_pop = ifid_consumed_i && ifid_valid_o;
    assign frontend_used = {1'b0, fifo_count_q} +
                           {1'b0, req_count_q} +
                           {2'b0, req_hold_valid_q};
    assign issue_has_credit = (frontend_used < 3'd2) || fifo_pop;

    assign new_request_valid = !halted_i && !front_stop_q &&
                               !external_flush_event && issue_has_credit &&
                               (fetch_pc_q[1:0] == 2'b00);
    assign imem_req_o = !rst_i && (req_hold_valid_q || new_request_valid);
    assign imem_addr_o = req_hold_valid_q ? req_hold_pc_q : fetch_pc_q;
    assign request_accept = imem_req_o && imem_gnt_i;
    assign request_capture_hold = !rst_i && !req_hold_valid_q &&
                                  new_request_valid && !imem_gnt_i;
    assign request_pc = req_hold_valid_q ? req_hold_pc_q : fetch_pc_q;
    assign request_kill = req_hold_valid_q && req_hold_kill_q;
    assign request_live = !request_kill &&
                          !external_flush_event;

    // Mỗi đáp ứng lấy metadata đầu hàng đợi, kể cả đáp ứng đã bị hủy.
    assign response_pop = imem_rvalid_i && (req_count_q != 2'd0);
    assign response_live = response_pop &&
                           !req_kill0_q &&
                           !external_flush_event && !front_stop_q;
    assign response_push = response_live;
    assign fetch_exception_event = response_push && imem_err_i;

    // Vector reset lệch hàng tạo ngoại lệ tại IF; đích nhánh được kiểm tra ở EX.
    assign local_misaligned_push = !rst_i && !halted_i &&
                                   !front_stop_q &&
                                   !external_flush_event &&
                                   (req_count_q == 2'd0) &&
                                   !req_hold_valid_q &&
                                   issue_has_credit &&
                                   (fetch_pc_q[1:0] != 2'b00);
    assign fifo_push = response_push || local_misaligned_push;
    assign push_pc = response_push ? req_pc0_q : fetch_pc_q;
    assign push_instr = (response_push && !imem_err_i)
                      ? imem_rdata_i : 32'b0;
    assign push_exc = local_misaligned_push || imem_err_i;
    assign push_cause = local_misaligned_push
                      ? CAUSE_INSTR_ADDR_MISALIGNED
                      : CAUSE_INSTR_ACCESS_FAULT;

    assign debug_fetch_pc_o = fetch_pc_q;

    always @(posedge clk_i) begin
        if (rst_i) begin
            front_stop_q   <= 1'b0;
            fetch_pc_q     <= RESET_VECTOR;
            req_hold_valid_q <= 1'b0;
            req_hold_pc_q  <= 32'b0;
            req_hold_kill_q <= 1'b0;
            req_count_q    <= 2'd0;
            req_pc0_q      <= 32'b0;
            req_pc1_q      <= 32'b0;
            req_kill0_q    <= 1'b0;
            req_kill1_q    <= 1'b0;
            fifo_count_q   <= 2'd0;
            fifo_pc0_q     <= 32'b0;
            fifo_pc1_q     <= 32'b0;
            fifo_instr0_q  <= 32'b0;
            fifo_instr1_q  <= 32'b0;
            fifo_exc0_q    <= 1'b0;
            fifo_exc1_q    <= 1'b0;
            fifo_cause0_q  <= 5'b0;
            fifo_cause1_q  <= 5'b0;
        end
        else begin
            if (ex_redirect_event_i)
                fetch_pc_q <= ex_control_target_i;
            else if (request_accept && request_live)
                fetch_pc_q <= request_pc + 32'd4;

            if (request_accept)
                req_hold_valid_q <= 1'b0;
            else if (request_capture_hold) begin
                req_hold_valid_q <= 1'b1;
                req_hold_pc_q <= fetch_pc_q;
                req_hold_kill_q <= 1'b0;
            end

            if (stop_event || fetch_exception_event ||
                local_misaligned_push)
                front_stop_q <= 1'b1;
            else if (ex_redirect_event_i)
                front_stop_q <= 1'b0;

            // Cập nhật hàng đợi yêu cầu chưa có đáp ứng.
            case ({request_accept, response_pop})
                2'b10: begin
                    if (req_count_q == 2'd0) begin
                        req_pc0_q    <= request_pc;
                        req_kill0_q  <= request_kill;
                    end
                    else begin
                        req_pc1_q    <= request_pc;
                        req_kill1_q  <= request_kill;
                    end
                    req_count_q <= req_count_q + 2'd1;
                end
                2'b01: begin
                    if (req_count_q == 2'd2) begin
                        req_pc0_q    <= req_pc1_q;
                        req_kill0_q  <= req_kill1_q;
                    end
                    req_count_q <= req_count_q - 2'd1;
                end
                2'b11: begin
                    if (req_count_q == 2'd1) begin
                        req_pc0_q    <= request_pc;
                        req_kill0_q  <= request_kill;
                    end
                    else begin
                        req_pc0_q    <= req_pc1_q;
                        req_kill0_q  <= req_kill1_q;
                        req_pc1_q    <= request_pc;
                        req_kill1_q  <= request_kill;
                    end
                end
                default: begin end
            endcase

            // Ưu tiên hủy sau cập nhật hàng đợi: cả yêu cầu vừa được grant hoặc
            // vừa chuyển sang trạng thái giữ trong chu kỳ lỗi đều phải bị hủy.
            if (external_flush_event || fetch_exception_event ||
                local_misaligned_push) begin
                req_hold_kill_q <= 1'b1;
                req_kill0_q <= 1'b1;
                req_kill1_q <= 1'b1;
            end

            // Flush xóa FIFO; giữ metadata để nhận và loại bỏ đáp ứng cũ.
            if (external_flush_event) begin
                fifo_count_q <= 2'd0;
            end
            else begin
                case ({fifo_push, fifo_pop})
                    2'b10: begin
                        if (fifo_count_q == 2'd0) begin
                            fifo_pc0_q    <= push_pc;
                            fifo_instr0_q <= push_instr;
                            fifo_exc0_q   <= push_exc;
                            fifo_cause0_q <= push_cause;
                        end
                        else begin
                            fifo_pc1_q    <= push_pc;
                            fifo_instr1_q <= push_instr;
                            fifo_exc1_q   <= push_exc;
                            fifo_cause1_q <= push_cause;
                        end
                        fifo_count_q <= fifo_count_q + 2'd1;
                    end
                    2'b01: begin
                        if (fifo_count_q == 2'd2) begin
                            fifo_pc0_q    <= fifo_pc1_q;
                            fifo_instr0_q <= fifo_instr1_q;
                            fifo_exc0_q   <= fifo_exc1_q;
                            fifo_cause0_q <= fifo_cause1_q;
                        end
                        fifo_count_q <= fifo_count_q - 2'd1;
                    end
                    2'b11: begin
                        if (fifo_count_q == 2'd1) begin
                            fifo_pc0_q    <= push_pc;
                            fifo_instr0_q <= push_instr;
                            fifo_exc0_q   <= push_exc;
                            fifo_cause0_q <= push_cause;
                        end
                        else begin
                            fifo_pc0_q    <= fifo_pc1_q;
                            fifo_instr0_q <= fifo_instr1_q;
                            fifo_exc0_q   <= fifo_exc1_q;
                            fifo_cause0_q <= fifo_cause1_q;
                            fifo_pc1_q    <= push_pc;
                            fifo_instr1_q <= push_instr;
                            fifo_exc1_q   <= push_exc;
                            fifo_cause1_q <= push_cause;
                        end
                    end
                    default: begin end
                endcase
            end
        end
    end

endmodule

`default_nettype wire

rtl\\core\\mem\\rv32_mem_stage.v:
`default_nettype none
`include "rv32_defs.vh"

// MEM: giao dịch dữ liệu word, phát hiện chờ/lỗi và chọn dữ liệu ghi về WB.
// Logic tổ hợp; core giữ EX/MEM và toàn bộ payload khi req && !ready.
// Giao dịch hoàn tất tại cạnh req && ready; err chỉ có nghĩa tại cạnh đó.
// Chi tiết bus dữ liệu: docs/giao_tiep_rtl_vi.md, mục 3.
module rv32_mem_stage (
    input  wire         rst_i,
    input  wire         halted_i,
    input  wire         wb_trap_event_i,
    input  wire         valid_i,
    input  wire         exc_valid_i,
    input  wire         load_i,
    input  wire         store_i,
    input  wire [31:0]  alu_result_i,
    input  wire [31:0]  store_data_i,
    input  wire [2:0]   funct3_i,
    input  wire [1:0]   wb_sel_i,
    input  wire [31:0]  pc4_i,
    input  wire [31:0]  dmem_rdata_i,
    input  wire         dmem_ready_i,
    input  wire         dmem_err_i,
    output wire         dmem_req_o,
    output wire         dmem_we_o,
    output wire [31:0]  dmem_addr_o,
    output wire [31:0]  dmem_wdata_o,
    output wire [3:0]   dmem_wstrb_o,
    output wire         stall_o,
    output wire         fault_raw_o,
    output reg  [31:0]  wb_data_o
);
    localparam [1:0] WB_LOAD = `RV32_WB_LOAD;
    localparam [1:0] WB_PC4 = `RV32_WB_PC4;

    wire [31:0] mem_lsu_addr;
    wire [31:0] mem_lsu_wdata;
    wire [3:0]  mem_lsu_wstrb;
    wire [31:0] mem_load_data;
    wire        mem_lsu_misaligned_unused;

    rv32_lsu u_lsu_mem (
        .addr_i         (alu_result_i),
        .funct3_i       (funct3_i),
        .load_en_i      (load_i),
        .store_en_i     (store_i),
        .store_data_i   (store_data_i),
        .load_data_i    (dmem_rdata_i),
        .mem_addr_o     (mem_lsu_addr),
        .mem_wdata_o    (mem_lsu_wdata),
        .mem_wstrb_o    (mem_lsu_wstrb),
        .load_data_o    (mem_load_data),
        .misaligned_o   (mem_lsu_misaligned_unused)
    );

    assign dmem_req_o = valid_i && !exc_valid_i &&
                        (load_i || store_i) &&
                        !rst_i && !halted_i && !wb_trap_event_i;
    assign dmem_we_o    = dmem_req_o && store_i;
    assign dmem_addr_o  = mem_lsu_addr;
    assign dmem_wdata_o = mem_lsu_wdata;
    assign dmem_wstrb_o = dmem_we_o ? mem_lsu_wstrb : 4'b0000;

    wire dmem_fire;

    assign dmem_fire    = dmem_req_o && dmem_ready_i;
    assign stall_o    = dmem_req_o && !dmem_ready_i;
    assign fault_raw_o = dmem_fire && dmem_err_i;

    always @(*) begin
        case (wb_sel_i)
            WB_LOAD: wb_data_o = mem_load_data;
            WB_PC4 : wb_data_o = pc4_i;
            default: wb_data_o = alu_result_i;
        endcase
    end

endmodule

`default_nettype wire

