`default_nettype none

`include "rv32_defs.vh"

// =============================================================================
// Module      : rv32_core
// Chức năng   : Core RV32I pipeline 5 tầng, in-order, single-issue.
// Pipeline    : IF -> ID -> EX -> MEM -> WB.
// ISA         : RV32I v2.1; không gồm C, M, A, Zicsr hay Zifencei.
//
// Giao tiếp bộ nhớ
//   - Instruction request được nhận tại req && gnt; response có rvalid riêng,
//     trả đúng thứ tự, sớm nhất ở cạnh kế tiếp. Không có rready.
//   - rdata/err instruction chỉ được lấy mẫu khi rvalid=1.
//   - Data bus giữ req và payload tới cạnh req && ready; tối đa một giao dịch.
//   - imem_addr_o là địa chỉ byte, luôn căn 4 khi phát request.
//   - dmem_addr_o là địa chỉ word đã căn; wstrb chọn byte lane little-endian.
//   - Pipeline dừng phía trước MEM khi data bus có wait-state. Instruction bus
//     dành trước chỗ trong FIFO hai phần tử cho mọi yêu cầu đã phát.
//   - Tổng FIFO, yêu cầu chờ đáp ứng và yêu cầu chờ grant không vượt hai.
//
// Hazard và control flow
//   - Forward EX/MEM -> EX và MEM/WB -> EX; EX/MEM có ưu tiên cao hơn.
//   - Load-use chèn một bubble. Nếu load bị wait-state, các tầng trước giữ lại.
//   - Branch/JAL/JALR được giải quyết tại EX; lệnh trẻ hơn bị flush khi redirect.
//   - Register file có bypass WB -> ID cho phụ thuộc cùng chu kỳ ghi.
//
// Ngoại lệ và retirement
//   - Hỗ trợ instruction/data access fault, địa chỉ lệch hàng, illegal,
//     EBREAK và ECALL. Ngoại lệ đi theo pipeline tới WB để giữ tính precise.
//   - Ngoại lệ đến WB chốt trap_valid_o và dừng core tới reset; không retire.
//   - FENCE là NOP hợp lệ: core in-order, không cache, chỉ có một data request.
//   - retire_* tạo giao tiếp trace một chu kỳ cho mỗi lệnh hoàn tất thành công.
//
// Reset
//   - rst_i tích cực mức cao, đồng bộ. PC fetch về RESET_VECTOR; pipeline rỗng.
//   - Core và memory phải reset đồng thời để hủy mọi đáp ứng cũ.
//   - Ngoài reset, yêu cầu lấy lệnh giữ tới grant, yêu cầu dữ liệu giữ tới ready.
// Đặc tả      : docs/giao_tiep_rtl_vi.md (phiên bản giao tiếp 2.0).
// =============================================================================
module rv32_core #(
    parameter [31:0] RESET_VECTOR = 32'h0000_0000
) (
    input  wire        clk_i,
    input  wire        rst_i,

    // Lấy lệnh: kênh yêu cầu và kênh đáp ứng tách pha, không có transaction ID.
    output wire        imem_req_o,
    output wire [31:0] imem_addr_o,
    input  wire        imem_gnt_i,
    input  wire        imem_rvalid_i,
    input  wire [31:0] imem_rdata_i,
    input  wire        imem_err_i,

    // Dữ liệu: bus word little-endian; wstrb chọn byte, err có nghĩa tại ready.
    output wire        dmem_req_o,
    output wire        dmem_we_o,
    output wire [31:0] dmem_addr_o,
    output wire [31:0] dmem_wdata_o,
    output wire [3:0]  dmem_wstrb_o,
    input  wire [31:0] dmem_rdata_i,
    input  wire        dmem_ready_i,
    input  wire        dmem_err_i,

    // Ngoại lệ: trạng thái chốt tại WB, giữ đến reset.
    output wire        halted_o,
    output wire        trap_valid_o,
    output wire [4:0]  trap_cause_o,
    output wire [31:0] trap_pc_o,
    output wire [31:0] trap_instr_o,

    // Trace: dữ liệu có nghĩa khi retire_valid=1; không phải giao tiếp RVFI.
    output wire        retire_valid_o,
    output wire [31:0] retire_pc_o,
    output wire [31:0] retire_instr_o,
    output wire        retire_rd_we_o,
    output wire [4:0]  retire_rd_addr_o,
    output wire [31:0] retire_rd_data_o,

    output wire [31:0] debug_fetch_pc_o
);

    localparam [1:0] OP_A_RS1 = `RV32_OP_A_RS1;
    localparam [1:0] WB_ALU = `RV32_WB_ALU;
    localparam [4:0] CAUSE_LOAD_ACCESS_FAULT = `RV32_CAUSE_LOAD_ACCESS_FAULT;
    localparam [4:0] CAUSE_STORE_ACCESS_FAULT = `RV32_CAUSE_STORE_ACCESS_FAULT;

    reg         idex_valid_q;
    reg  [31:0] idex_pc_q;
    reg  [31:0] idex_instr_q;
    reg  [31:0] idex_pc4_q;
    reg  [4:0]  idex_rs1_addr_q;
    reg  [4:0]  idex_rs2_addr_q;
    reg  [4:0]  idex_rd_addr_q;
    reg  [31:0] idex_rs1_data_q;
    reg  [31:0] idex_rs2_data_q;
    reg  [31:0] idex_imm_q;
    reg  [2:0]  idex_funct3_q;
    reg  [3:0]  idex_alu_op_q;
    reg  [1:0]  idex_op_a_sel_q;
    reg         idex_op_b_imm_q;
    reg         idex_reg_write_q;
    reg  [1:0]  idex_wb_sel_q;
    reg         idex_branch_q;
    reg         idex_jal_q;
    reg         idex_jalr_q;
    reg         idex_load_q;
    reg         idex_store_q;
    reg         idex_exc_valid_q;
    reg  [4:0]  idex_exc_cause_q;

    reg         exmem_valid_q;
    reg  [31:0] exmem_pc_q;
    reg  [31:0] exmem_instr_q;
    reg  [31:0] exmem_pc4_q;
    reg  [4:0]  exmem_rd_addr_q;
    reg         exmem_reg_write_q;
    reg  [1:0]  exmem_wb_sel_q;
    reg  [31:0] exmem_alu_result_q;
    reg  [31:0] exmem_store_data_q;
    reg  [2:0]  exmem_funct3_q;
    reg         exmem_load_q;
    reg         exmem_store_q;
    reg         exmem_exc_valid_q;
    reg  [4:0]  exmem_exc_cause_q;

    reg         memwb_valid_q;
    reg  [31:0] memwb_pc_q;
    reg  [31:0] memwb_instr_q;
    reg  [4:0]  memwb_rd_addr_q;
    reg         memwb_reg_write_q;
    reg  [31:0] memwb_wb_data_q;
    reg         memwb_exc_valid_q;
    reg  [4:0]  memwb_exc_cause_q;

    wire         ifid_valid_q;
    wire [31:0]  ifid_pc_q;
    wire [31:0]  ifid_instr_q;
    wire         ifid_exc_valid_q;
    wire [4:0]   ifid_exc_cause_q;
    wire [4:0]   id_rs1_addr;
    wire [4:0]   id_rs2_addr;
    wire [4:0]   id_rd_addr;
    wire [2:0]   id_funct3;
    wire [31:0]  id_rs1_data;
    wire [31:0]  id_rs2_data;
    wire [31:0]  id_imm;
    wire [3:0]   id_alu_op;
    wire [1:0]   id_op_a_sel;
    wire         id_op_b_imm;
    wire         id_reg_write;
    wire [1:0]   id_wb_sel;
    wire         id_branch;
    wire         id_jal;
    wire         id_jalr;
    wire         id_load;
    wire         id_store;
    wire         id_uses_rs1;
    wire         id_uses_rs2;
    wire         id_decode_exc;
    wire         id_any_exc;
    wire [4:0]   id_any_exc_cause;
    wire [31:0]  ex_rs1_value;
    wire [31:0]  ex_rs2_value;
    wire [31:0]  ex_alu_result;
    wire [31:0]  ex_control_target;
    wire         ex_control_taken;
    wire         ex_target_misaligned;
    wire         ex_fault_raw;
    wire [4:0]   ex_fault_cause;
    wire         mem_stall;
    wire         mem_fault_raw;
    wire [31:0]  mem_wb_data;
    wire         wb_regfile_we;
    wire         wb_trap_event;
    wire         halted_q;

    wire [1:0]   forward_rs1_sel;
    wire [1:0]   forward_rs2_sel;
    wire         mem_fault_event;
    wire         ex_fault_event;
    wire         ex_redirect_event;
    wire         id_exception_event;
    wire         load_use_stall;
    wire         ifid_consumed;

    assign halted_o = halted_q;

    // IF: quản lý yêu cầu, FIFO lệnh và nhận/bỏ đáp ứng sai đường.
    rv32_if_stage #(.RESET_VECTOR(RESET_VECTOR)) u_if_stage (
        .clk_i(clk_i),
        .rst_i(rst_i),
        .halted_i(halted_q),
        .wb_trap_event_i(wb_trap_event),
        .mem_fault_event_i(mem_fault_event),
        .ex_fault_event_i(ex_fault_event),
        .ex_redirect_event_i(ex_redirect_event),
        .id_exception_event_i(id_exception_event),
        .ex_control_target_i(ex_control_target),
        .ifid_consumed_i(ifid_consumed),
        .imem_gnt_i(imem_gnt_i),
        .imem_rvalid_i(imem_rvalid_i),
        .imem_rdata_i(imem_rdata_i),
        .imem_err_i(imem_err_i),
        .imem_req_o(imem_req_o),
        .imem_addr_o(imem_addr_o),
        .debug_fetch_pc_o(debug_fetch_pc_o),
        .ifid_valid_o(ifid_valid_q),
        .ifid_pc_o(ifid_pc_q),
        .ifid_instr_o(ifid_instr_q),
        .ifid_exc_valid_o(ifid_exc_valid_q),
        .ifid_exc_cause_o(ifid_exc_cause_q)
    );

    // ID: giải mã RV32I, tạo immediate, đọc thanh ghi và bypass từ WB.
    rv32_id_stage u_id_stage (
        .clk_i(clk_i),
        .rst_i(rst_i),
        .instr_i(ifid_instr_q),
        .exc_valid_i(ifid_exc_valid_q),
        .exc_cause_i(ifid_exc_cause_q),
        .wb_regfile_we_i(wb_regfile_we),
        .memwb_rd_addr_i(memwb_rd_addr_q),
        .memwb_wb_data_i(memwb_wb_data_q),
        .rs1_addr_o(id_rs1_addr),
        .rs2_addr_o(id_rs2_addr),
        .rd_addr_o(id_rd_addr),
        .funct3_o(id_funct3),
        .rs1_data_o(id_rs1_data),
        .rs2_data_o(id_rs2_data),
        .imm_o(id_imm),
        .alu_op_o(id_alu_op),
        .op_a_sel_o(id_op_a_sel),
        .op_b_imm_o(id_op_b_imm),
        .reg_write_o(id_reg_write),
        .wb_sel_o(id_wb_sel),
        .branch_o(id_branch),
        .jal_o(id_jal),
        .jalr_o(id_jalr),
        .load_o(id_load),
        .store_o(id_store),
        .uses_rs1_o(id_uses_rs1),
        .uses_rs2_o(id_uses_rs2),
        .decode_exc_o(id_decode_exc),
        .any_exc_o(id_any_exc),
        .any_exc_cause_o(id_any_exc_cause)
    );

    // EX: forwarding toán hạng, ALU/nhánh và phát hiện địa chỉ lệch hàng.
    rv32_ex_stage u_ex_stage (
        .valid_i(idex_valid_q),
        .exc_valid_i(idex_exc_valid_q),
        .rs1_data_i(idex_rs1_data_q),
        .rs2_data_i(idex_rs2_data_q),
        .op_a_sel_i(idex_op_a_sel_q),
        .op_b_imm_i(idex_op_b_imm_q),
        .pc_i(idex_pc_q),
        .imm_i(idex_imm_q),
        .alu_op_i(idex_alu_op_q),
        .branch_i(idex_branch_q),
        .funct3_i(idex_funct3_q),
        .jal_i(idex_jal_q),
        .jalr_i(idex_jalr_q),
        .load_i(idex_load_q),
        .store_i(idex_store_q),
        .exmem_wb_sel_i(exmem_wb_sel_q),
        .exmem_pc4_i(exmem_pc4_q),
        .exmem_alu_result_i(exmem_alu_result_q),
        .memwb_wb_data_i(memwb_wb_data_q),
        .forward_rs1_sel_i(forward_rs1_sel),
        .forward_rs2_sel_i(forward_rs2_sel),
        .rs1_value_o(ex_rs1_value),
        .rs2_value_o(ex_rs2_value),
        .alu_result_o(ex_alu_result),
        .control_target_o(ex_control_target),
        .control_taken_o(ex_control_taken),
        .target_misaligned_o(ex_target_misaligned),
        .fault_raw_o(ex_fault_raw),
        .fault_cause_o(ex_fault_cause)
    );

    // MEM: giao dịch dữ liệu, chờ đáp ứng, phát hiện lỗi và chọn kết quả load.
    rv32_mem_stage u_mem_stage (
        .rst_i(rst_i),
        .halted_i(halted_q),
        .wb_trap_event_i(wb_trap_event),
        .valid_i(exmem_valid_q),
        .exc_valid_i(exmem_exc_valid_q),
        .load_i(exmem_load_q),
        .store_i(exmem_store_q),
        .alu_result_i(exmem_alu_result_q),
        .store_data_i(exmem_store_data_q),
        .funct3_i(exmem_funct3_q),
        .wb_sel_i(exmem_wb_sel_q),
        .pc4_i(exmem_pc4_q),
        .dmem_rdata_i(dmem_rdata_i),
        .dmem_ready_i(dmem_ready_i),
        .dmem_err_i(dmem_err_i),
        .dmem_req_o(dmem_req_o),
        .dmem_we_o(dmem_we_o),
        .dmem_addr_o(dmem_addr_o),
        .dmem_wdata_o(dmem_wdata_o),
        .dmem_wstrb_o(dmem_wstrb_o),
        .stall_o(mem_stall),
        .fault_raw_o(mem_fault_raw),
        .wb_data_o(mem_wb_data)
    );

    // WB: ghi thanh ghi, trace lệnh hoàn tất và chốt ngoại lệ chính xác.
    rv32_wb_stage u_wb_stage (
        .clk_i(clk_i),
        .rst_i(rst_i),
        .valid_i(memwb_valid_q),
        .exc_valid_i(memwb_exc_valid_q),
        .reg_write_i(memwb_reg_write_q),
        .rd_addr_i(memwb_rd_addr_q),
        .wb_data_i(memwb_wb_data_q),
        .pc_i(memwb_pc_q),
        .instr_i(memwb_instr_q),
        .exc_cause_i(memwb_exc_cause_q),
        .wb_regfile_we_o(wb_regfile_we),
        .wb_trap_event_o(wb_trap_event),
        .halted_o(halted_q),
        .trap_valid_o(trap_valid_o),
        .trap_cause_o(trap_cause_o),
        .trap_pc_o(trap_pc_o),
        .trap_instr_o(trap_instr_o),
        .retire_valid_o(retire_valid_o),
        .retire_pc_o(retire_pc_o),
        .retire_instr_o(retire_instr_o),
        .retire_rd_we_o(retire_rd_we_o),
        .retire_rd_addr_o(retire_rd_addr_o),
        .retire_rd_data_o(retire_rd_data_o)
    );

    // Điều khiển: hazard/forwarding; sự kiện của lệnh già hơn có ưu tiên cao hơn.
    rv32_pipeline_control u_control (
        .id_rs1_addr_i(id_rs1_addr),
        .id_rs2_addr_i(id_rs2_addr),
        .id_uses_rs1_i(id_uses_rs1),
        .id_uses_rs2_i(id_uses_rs2),
        .idex_valid_i(idex_valid_q),
        .idex_exc_valid_i(idex_exc_valid_q),
        .idex_load_i(idex_load_q),
        .idex_rd_addr_i(idex_rd_addr_q),
        .idex_rs1_addr_i(idex_rs1_addr_q),
        .idex_rs2_addr_i(idex_rs2_addr_q),
        .exmem_valid_i(exmem_valid_q),
        .exmem_exc_valid_i(exmem_exc_valid_q),
        .exmem_reg_write_i(exmem_reg_write_q),
        .exmem_load_i(exmem_load_q),
        .exmem_rd_addr_i(exmem_rd_addr_q),
        .memwb_valid_i(memwb_valid_q),
        .memwb_exc_valid_i(memwb_exc_valid_q),
        .memwb_reg_write_i(memwb_reg_write_q),
        .memwb_rd_addr_i(memwb_rd_addr_q),
        .mem_fault_raw_i(mem_fault_raw),
        .mem_stall_i(mem_stall),
        .ex_fault_raw_i(ex_fault_raw),
        .ex_control_taken_i(ex_control_taken),
        .ex_target_misaligned_i(ex_target_misaligned),
        .ifid_valid_i(ifid_valid_q),
        .ifid_exc_valid_i(ifid_exc_valid_q),
        .id_decode_exc_i(id_decode_exc),
        .halted_i(halted_q),
        .wb_trap_event_i(wb_trap_event),
        .forward_rs1_sel_o(forward_rs1_sel),
        .forward_rs2_sel_o(forward_rs2_sel),
        .mem_fault_event_o(mem_fault_event),
        .ex_fault_event_o(ex_fault_event),
        .ex_redirect_event_o(ex_redirect_event),
        .id_exception_event_o(id_exception_event),
        .load_use_stall_o(load_use_stall),
        .ifid_consumed_o(ifid_consumed)
    );

    // Thanh ghi ID/EX, EX/MEM và MEM/WB; IF/ID thuộc FIFO của IF.
    // Payload chỉ có nghĩa khi bit valid tương ứng bằng 1.
    always @(posedge clk_i) begin
        if (rst_i) begin
            idex_valid_q        <= 1'b0;
            idex_pc_q           <= 32'b0;
            idex_instr_q        <= 32'b0;
            idex_pc4_q          <= 32'b0;
            idex_rs1_addr_q     <= 5'b0;
            idex_rs2_addr_q     <= 5'b0;
            idex_rd_addr_q      <= 5'b0;
            idex_rs1_data_q     <= 32'b0;
            idex_rs2_data_q     <= 32'b0;
            idex_imm_q          <= 32'b0;
            idex_funct3_q       <= 3'b0;
            idex_alu_op_q       <= 4'b0;
            idex_op_a_sel_q     <= OP_A_RS1;
            idex_op_b_imm_q     <= 1'b0;
            idex_reg_write_q    <= 1'b0;
            idex_wb_sel_q       <= WB_ALU;
            idex_branch_q       <= 1'b0;
            idex_jal_q          <= 1'b0;
            idex_jalr_q         <= 1'b0;
            idex_load_q         <= 1'b0;
            idex_store_q        <= 1'b0;
            idex_exc_valid_q    <= 1'b0;
            idex_exc_cause_q    <= 5'b0;

            exmem_valid_q       <= 1'b0;
            exmem_pc_q          <= 32'b0;
            exmem_instr_q       <= 32'b0;
            exmem_pc4_q         <= 32'b0;
            exmem_rd_addr_q     <= 5'b0;
            exmem_reg_write_q   <= 1'b0;
            exmem_wb_sel_q      <= WB_ALU;
            exmem_alu_result_q  <= 32'b0;
            exmem_store_data_q  <= 32'b0;
            exmem_funct3_q      <= 3'b0;
            exmem_load_q        <= 1'b0;
            exmem_store_q       <= 1'b0;
            exmem_exc_valid_q   <= 1'b0;
            exmem_exc_cause_q   <= 5'b0;

            memwb_valid_q       <= 1'b0;
            memwb_pc_q          <= 32'b0;
            memwb_instr_q       <= 32'b0;
            memwb_rd_addr_q     <= 5'b0;
            memwb_reg_write_q   <= 1'b0;
            memwb_wb_data_q     <= 32'b0;
            memwb_exc_valid_q   <= 1'b0;
            memwb_exc_cause_q   <= 5'b0;

        end
        else if (wb_trap_event) begin
            idex_valid_q <= 1'b0;
            exmem_valid_q <= 1'b0;
            memwb_valid_q <= 1'b0;
        end
        else if (!halted_q) begin
            // ---------------------------- MEM/WB -------------------------
            if (mem_stall) begin
                // Lệnh WB cũ đã commit ở cạnh này; không được commit lặp.
                memwb_valid_q <= 1'b0;
            end
            else begin
                memwb_valid_q      <= exmem_valid_q;
                memwb_pc_q         <= exmem_pc_q;
                memwb_instr_q      <= exmem_instr_q;
                memwb_rd_addr_q    <= exmem_rd_addr_q;
                memwb_reg_write_q  <= exmem_reg_write_q &&
                                      !exmem_exc_valid_q &&
                                      !mem_fault_event;
                memwb_wb_data_q    <= mem_wb_data;
                memwb_exc_valid_q  <= exmem_exc_valid_q ||
                                      mem_fault_event;
                if (exmem_exc_valid_q) begin
                    memwb_exc_cause_q <= exmem_exc_cause_q;
                end
                else if (exmem_load_q) begin
                    memwb_exc_cause_q <= CAUSE_LOAD_ACCESS_FAULT;
                end
                else begin
                    memwb_exc_cause_q <= CAUSE_STORE_ACCESS_FAULT;
                end
            end

            // ---------------------------- EX/MEM -------------------------
            if (mem_fault_event) begin
                // MEM fault thuộc lệnh già hơn; hủy mọi kết quả từ EX.
                exmem_valid_q <= 1'b0;
            end
            else if (!mem_stall) begin
                exmem_valid_q      <= idex_valid_q;
                exmem_pc_q         <= idex_pc_q;
                exmem_instr_q      <= idex_instr_q;
                exmem_pc4_q        <= idex_pc4_q;
                exmem_rd_addr_q    <= idex_rd_addr_q;
                exmem_reg_write_q  <= idex_reg_write_q &&
                                      !idex_exc_valid_q &&
                                      !ex_fault_raw;
                exmem_wb_sel_q     <= idex_wb_sel_q;
                exmem_alu_result_q <= ex_alu_result;
                exmem_store_data_q <= ex_rs2_value;
                exmem_funct3_q     <= idex_funct3_q;
                exmem_load_q       <= idex_load_q &&
                                      !idex_exc_valid_q &&
                                      !ex_fault_raw;
                exmem_store_q      <= idex_store_q &&
                                      !idex_exc_valid_q &&
                                      !ex_fault_raw;
                exmem_exc_valid_q  <= idex_exc_valid_q || ex_fault_raw;
                exmem_exc_cause_q  <= idex_exc_valid_q
                                    ? idex_exc_cause_q
                                    : ex_fault_cause;
            end

            // ---------------------------- ID/EX --------------------------
            if (mem_fault_event || ex_fault_event || ex_redirect_event) begin
                idex_valid_q <= 1'b0;
            end
            else if (mem_stall) begin
                // WB có thể commit trong lúc MEM đang chờ. Chốt giá trị đã
                // forwarding vào ID/EX để consumer không mất dữ liệu sau
                // khi MEM/WB được clear ở chu kỳ stall kế tiếp.
                idex_rs1_data_q <= ex_rs1_value;
                idex_rs2_data_q <= ex_rs2_value;
            end
            else if (load_use_stall) begin
                idex_valid_q <= 1'b0;
            end
            else begin
                idex_valid_q      <= ifid_valid_q;
                idex_pc_q         <= ifid_pc_q;
                idex_instr_q      <= ifid_instr_q;
                idex_pc4_q        <= ifid_pc_q + 32'd4;
                idex_rs1_addr_q   <= id_rs1_addr;
                idex_rs2_addr_q   <= id_rs2_addr;
                idex_rd_addr_q    <= id_rd_addr;
                idex_rs1_data_q   <= id_rs1_data;
                idex_rs2_data_q   <= id_rs2_data;
                idex_imm_q        <= id_imm;
                idex_funct3_q     <= id_funct3;
                idex_alu_op_q     <= id_alu_op;
                idex_op_a_sel_q   <= id_op_a_sel;
                idex_op_b_imm_q   <= id_op_b_imm;
                idex_reg_write_q  <= id_reg_write && !id_any_exc;
                idex_wb_sel_q     <= id_wb_sel;
                idex_branch_q     <= id_branch && !id_any_exc;
                idex_jal_q        <= id_jal && !id_any_exc;
                idex_jalr_q       <= id_jalr && !id_any_exc;
                idex_load_q       <= id_load && !id_any_exc;
                idex_store_q      <= id_store && !id_any_exc;
                idex_exc_valid_q  <= id_any_exc;
                idex_exc_cause_q  <= id_any_exc_cause;
            end

        end
    end

endmodule

`default_nettype wire

rtl\\core\\wb\\rv32_wb_stage.v:
`default_nettype none
`include "rv32_defs.vh"

// WB: commit thanh ghi, trace lệnh hoàn tất và chốt ngoại lệ chính xác.
// Cạnh lên thực hiện commit khi MEM/WB hợp lệ, không lỗi và core chưa halt.
// Trace có nghĩa trong chu kỳ ngay sau cạnh commit; trap/halt giữ tới reset.
// Lệnh lỗi không retire và không ghi rd. Reset đồng bộ, tích cực cao.
// Chi tiết trace/trap: docs/giao_tiep_rtl_vi.md, mục 6.
module rv32_wb_stage (
    input  wire         clk_i,
    input  wire         rst_i,
    input  wire         valid_i,
    input  wire         exc_valid_i,
    input  wire         reg_write_i,
    input  wire [4:0]   rd_addr_i,
    input  wire [31:0]  wb_data_i,
    input  wire [31:0]  pc_i,
    input  wire [31:0]  instr_i,
    input  wire [4:0]   exc_cause_i,
    output wire         wb_regfile_we_o,
    output wire         wb_trap_event_o,
    output reg          halted_o,
    output reg          trap_valid_o,
    output reg  [4:0]   trap_cause_o,
    output reg  [31:0]  trap_pc_o,
    output reg  [31:0]  trap_instr_o,
    output reg          retire_valid_o,
    output reg  [31:0]  retire_pc_o,
    output reg  [31:0]  retire_instr_o,
    output reg          retire_rd_we_o,
    output reg  [4:0]   retire_rd_addr_o,
    output reg  [31:0]  retire_rd_data_o
);

    assign wb_regfile_we_o = !rst_i && valid_i && !exc_valid_i &&
                           reg_write_i && (rd_addr_i != 5'd0) && !halted_o;
    assign wb_trap_event_o = valid_i && exc_valid_i && !halted_o && !rst_i;
    always @(posedge clk_i) begin
        if (rst_i) begin
            halted_o <= 1'b0;
            trap_valid_o        <= 1'b0;
            trap_cause_o        <= 5'b0;
            trap_pc_o           <= 32'b0;
            trap_instr_o        <= 32'b0;
            retire_valid_o      <= 1'b0;
            retire_pc_o         <= 32'b0;
            retire_instr_o      <= 32'b0;
            retire_rd_we_o      <= 1'b0;
            retire_rd_addr_o    <= 5'b0;
            retire_rd_data_o    <= 32'b0;
        end
        else begin
            retire_valid_o <= 1'b0;
            retire_rd_we_o <= 1'b0;

            // WB commit thanh ghi và trace; store đã hoàn tất handshake tại MEM.
            if (!halted_o && valid_i && !exc_valid_i) begin
                retire_valid_o   <= 1'b1;
                retire_pc_o      <= pc_i;
                retire_instr_o   <= instr_i;
                retire_rd_we_o   <= reg_write_i &&
                                    (rd_addr_i != 5'd0);
                retire_rd_addr_o <= rd_addr_i;
                retire_rd_data_o <= wb_data_i;
            end

            if (wb_trap_event_o) begin
                halted_o <= 1'b1;
                trap_valid_o <= 1'b1;
                trap_cause_o <= exc_cause_i;
                trap_pc_o <= pc_i;
                trap_instr_o <= instr_i;
            end
        end
    end

endmodule

`default_nettype wire

rtl\\memory\\intel_sync_ram_1p.v:
`default_nettype none

// =============================================================================
// Module      : intel_sync_ram_1p
// Chức năng   : RAM đồng bộ một cổng, 32 bit, có byte write-enable.
//
// Khi tổng hợp cho MAX 10, wrapper dùng altsyncram để kết quả ánh xạ chắc chắn
// vào M9K. Khi mô phỏng RTL, mảng Verilog giữ khả năng quan sát và không cần
// thư viện primitive Intel. Dữ liệu đọc xuất hiện sau cạnh clock có en_i=1.
// =============================================================================
module intel_sync_ram_1p #(
    parameter integer WIDTH = 32,
    parameter integer WORDS = 2048,
    parameter integer ADDR_WIDTH = 11,
    parameter integer BYTE_COUNT = 4
) (
    input  wire                       clk_i,
    input  wire                       en_i,
    input  wire                       we_i,
    input  wire [BYTE_COUNT-1:0]      byteena_i,
    input  wire [ADDR_WIDTH-1:0]      addr_i,
    input  wire [WIDTH-1:0]           data_i,
    output wire [WIDTH-1:0]           q_o
);

`ifdef FPGA_SYNTHESIS
    wire [WIDTH-1:0] ram_q;

    altsyncram u_altsyncram (
        .address_a(addr_i),
        .clock0(clk_i),
        .rden_a(en_i),
        .wren_a(en_i && we_i),
        .byteena_a(byteena_i),
        .data_a(data_i),
        .q_a(ram_q),
        .aclr0(1'b0),
        .addressstall_a(1'b0)
    );
    defparam
        u_altsyncram.intended_device_family = "MAX 10",
        u_altsyncram.operation_mode = "SINGLE_PORT",
        u_altsyncram.width_a = WIDTH,
        u_altsyncram.widthad_a = ADDR_WIDTH,
        u_altsyncram.numwords_a = WORDS,
        u_altsyncram.width_byteena_a = BYTE_COUNT,
        u_altsyncram.byte_size = 8,
        u_altsyncram.outdata_reg_a = "UNREGISTERED",
        u_altsyncram.read_during_write_mode_port_a = "OLD_DATA",
        u_altsyncram.lpm_type = "altsyncram";

    assign q_o = ram_q;
`else
    reg [WIDTH-1:0] mem [0:WORDS-1];
    reg [WIDTH-1:0] q_q;
    integer byte_index;

    always @(posedge clk_i) begin
        if (en_i) begin
            q_q <= mem[addr_i];
            if (we_i) begin
                for (byte_index = 0; byte_index < BYTE_COUNT;
                     byte_index = byte_index + 1) begin
                    if (byteena_i[byte_index])
                        mem[addr_i][byte_index*8 +: 8] <=
                            data_i[byte_index*8 +: 8];
                end
            end
        end
    end

    assign q_o = q_q;
`endif

endmodule

`default_nettype wire

rtl\\memory\\intel_sync_rom_1p.v:
`default_nettype none

// =============================================================================
// Module      : intel_sync_rom_1p
// Chức năng   : ROM đồng bộ một cổng, có backend altsyncram cho MAX 10.
//
// FPGA_SYNTHESIS được QSF định nghĩa khi chạy Quartus. Mô phỏng RTL dùng mảng
// Verilog để testbench có thể nạp vector trực tiếp; tổng hợp dùng primitive để
// bảo đảm trọng số lớn nằm trong M9K thay vì bị trải thành LUT/flip-flop.
// =============================================================================
module intel_sync_rom_1p #(
    parameter integer WIDTH = 8,
    parameter integer WORDS = 256,
    parameter integer ADDR_WIDTH = 8,
    parameter integer USE_INIT_FILE = 0,
    parameter         INIT_FILE = "UNUSED"
) (
    input  wire                  clk_i,
    input  wire                  en_i,
    input  wire [ADDR_WIDTH-1:0] addr_i,
    output wire [WIDTH-1:0]      q_o
);

`ifdef FPGA_SYNTHESIS
    wire [WIDTH-1:0] rom_q;

    altsyncram u_altsyncram (
        .address_a(addr_i),
        .clock0(clk_i),
        .rden_a(en_i),
        .q_a(rom_q),
        .aclr0(1'b0),
        .addressstall_a(1'b0),
        .byteena_a(1'b1),
        .data_a({WIDTH{1'b0}}),
        .wren_a(1'b0)
    );
    defparam
        u_altsyncram.intended_device_family = "MAX 10",
        u_altsyncram.operation_mode = "ROM",
        u_altsyncram.width_a = WIDTH,
        u_altsyncram.widthad_a = ADDR_WIDTH,
        u_altsyncram.numwords_a = WORDS,
        u_altsyncram.outdata_reg_a = "UNREGISTERED",
        u_altsyncram.init_file = INIT_FILE,
        u_altsyncram.lpm_type = "altsyncram";

    assign q_o = rom_q;
`else
    reg [WIDTH-1:0] mem [0:WORDS-1];
    reg [WIDTH-1:0] q_q;
    integer index;
    initial begin
        for (index = 0; index < WORDS; index = index + 1)
            mem[index] = {WIDTH{1'b0}};
        if (USE_INIT_FILE != 0)
            $readmemh(INIT_FILE, mem);
    end
    always @(posedge clk_i) begin
        if (en_i)
            q_q <= mem[addr_i];
    end
    assign q_o = q_q;
`endif

endmodule

`default_nettype wire

rtl\\memory\\intel_sync_rom_2p.v:
`default_nettype none

// =============================================================================
// Module      : intel_sync_rom_2p
// Chức năng   : ROM đồng bộ hai cổng đọc độc lập dùng chung một khối dữ liệu.
// Backend Quartus dùng altsyncram true-dual-port để ROM chương trình 128 KiB
// chỉ chiếm một bản trong M9K dù CPU đọc đồng thời instruction và .rodata.
// =============================================================================
module intel_sync_rom_2p #(
    parameter integer WIDTH = 32,
    parameter integer WORDS = 32768,
    parameter integer ADDR_WIDTH = 15,
    parameter integer USE_INIT_FILE = 0,
    parameter         INIT_FILE = "UNUSED"
) (
    input  wire                  clk_i,
    input  wire                  a_en_i,
    input  wire [ADDR_WIDTH-1:0] a_addr_i,
    output wire [WIDTH-1:0]      a_q_o,
    input  wire                  b_en_i,
    input  wire [ADDR_WIDTH-1:0] b_addr_i,
    output wire [WIDTH-1:0]      b_q_o
);

`ifdef FPGA_SYNTHESIS
    wire [WIDTH-1:0] rom_a_q;
    wire [WIDTH-1:0] rom_b_q;

    altsyncram u_altsyncram (
        .address_a(a_addr_i), .address_b(b_addr_i),
        .clock0(clk_i), .clock1(clk_i),
        .rden_a(a_en_i), .rden_b(b_en_i),
        .q_a(rom_a_q), .q_b(rom_b_q),
        .aclr0(1'b0), .aclr1(1'b0),
        .addressstall_a(1'b0), .addressstall_b(1'b0),
        .byteena_a(1'b1), .byteena_b(1'b1),
        .data_a({WIDTH{1'b0}}), .data_b({WIDTH{1'b0}}),
        .wren_a(1'b0), .wren_b(1'b0)
    );
    defparam
        u_altsyncram.intended_device_family = "MAX 10",
        u_altsyncram.operation_mode = "BIDIR_DUAL_PORT",
        u_altsyncram.width_a = WIDTH,
        u_altsyncram.widthad_a = ADDR_WIDTH,
        u_altsyncram.numwords_a = WORDS,
        u_altsyncram.width_b = WIDTH,
        u_altsyncram.widthad_b = ADDR_WIDTH,
        u_altsyncram.numwords_b = WORDS,
        u_altsyncram.address_reg_b = "CLOCK1",
        u_altsyncram.outdata_reg_a = "UNREGISTERED",
        u_altsyncram.outdata_reg_b = "UNREGISTERED",
        u_altsyncram.init_file = INIT_FILE,
        u_altsyncram.lpm_type = "altsyncram";

    assign a_q_o = rom_a_q;
    assign b_q_o = rom_b_q;
`else
    reg [WIDTH-1:0] mem [0:WORDS-1];
    reg [WIDTH-1:0] a_q;
    reg [WIDTH-1:0] b_q;
    initial begin
        if (USE_INIT_FILE != 0)
            $readmemh(INIT_FILE, mem);
    end
    always @(posedge clk_i) begin
        if (a_en_i) a_q <= mem[a_addr_i];
        if (b_en_i) b_q <= mem[b_addr_i];
    end
    assign a_q_o = a_q;
    assign b_q_o = b_q;
`endif

endmodule

`default_nettype wire

rtl\\memory\\soc_ram.v:
`default_nettype none

// =============================================================================
// Module      : soc_ram
// Chức năng   : SRAM on-chip 8 KiB mặc định, một cổng, byte write-enable.
//
// Giao thức:
//   - Master giữ req/address/write-data cho tới khi ready_o=1.
//   - Request hợp lệ được chụp ở một cạnh clock; ready/data trả ở chu kỳ sau.
//   - Địa chỉ ngoài vùng hoặc lệch word trả ready+err, không làm bus treo.
//
// Backend lưu trữ nằm trong intel_sync_ram_1p. Tách handshake khỏi primitive làm
// RTL dễ kiểm tra và tránh Quartus trải RAM thành FF/mux do process quá phức tạp.
// =============================================================================
module soc_ram #(
    parameter integer WORDS = 2048
) (
    input  wire        clk_i,
    input  wire        rst_i,
    input  wire        req_i,
    input  wire        we_i,
    input  wire [31:0] addr_i,
    input  wire [31:0] wdata_i,
    input  wire [3:0]  wstrb_i,
    output reg  [31:0] rdata_o,
    output reg         ready_o,
    output reg         err_o
);

    localparam [31:0] RAM_BYTES = WORDS * 4;

    function integer clog2;
        input integer value;
        integer temporary;
        begin
            temporary = value - 1;
            for (clog2 = 0; temporary > 0; clog2 = clog2 + 1)
                temporary = temporary >> 1;
        end
    endfunction

    localparam integer ADDR_WIDTH = (WORDS > 1) ? clog2(WORDS) : 1;
    reg pending_q;
    reg pending_err_q;

    wire valid_addr = (addr_i < RAM_BYTES) && (addr_i[1:0] == 2'b00);
    wire accept = req_i && !rst_i && !ready_o && !pending_q;
    wire ram_enable = accept && valid_addr;
    wire [31:0] ram_q;

    intel_sync_ram_1p #(
        .WIDTH(32), .WORDS(WORDS), .ADDR_WIDTH(ADDR_WIDTH), .BYTE_COUNT(4)
    ) u_storage (
        .clk_i(clk_i),
        .en_i(ram_enable),
        .we_i(we_i),
        .byteena_i(wstrb_i),
        .addr_i(addr_i[ADDR_WIDTH+1:2]),
        .data_i(wdata_i),
        .q_o(ram_q)
    );

    always @(posedge clk_i) begin
        if (rst_i) begin
            rdata_o      <= 32'd0;
            ready_o      <= 1'b0;
            err_o        <= 1'b0;
            pending_q    <= 1'b0;
            pending_err_q <= 1'b0;
        end
        else begin
            if (ready_o) begin
                ready_o <= 1'b0;
                err_o   <= 1'b0;
            end
            else if (pending_q) begin
                ready_o   <= 1'b1;
                err_o     <= pending_err_q;
                rdata_o   <= pending_err_q ? 32'd0 : ram_q;
                pending_q <= 1'b0;
            end
            else if (req_i) begin
                pending_q     <= 1'b1;
                pending_err_q <= !valid_addr;
            end
        end
    end

endmodule

`default_nettype wire

rtl\\memory\\soc_rom_dp.v:
`default_nettype none

// =============================================================================
// Module      : soc_rom_dp
// Chức năng   : ROM hai cổng đọc đồng bộ cho instruction và data.
//
// Giao thức:
//   - Cổng instruction tách request/response. req && gnt nhận một địa chỉ mới;
//     rvalid trả kết quả theo thứ tự sau một chu kỳ và có thể liên tiếp mỗi chu kỳ.
//   - Cổng data giữ req/địa chỉ tới cạnh req && ready; tối đa một giao dịch.
//     Chụp nội bộ ở N, master lấy đáp ứng ở N+2; chụp tiếp sớm nhất ở N+3.
//   - err đi cùng rvalid (instruction) hoặc ready (data).
//   - Reset tích cực cao, đồng bộ; hủy giao dịch nhưng không xóa nội dung ROM.
//   - WORDS phải dương, 4*WORDS biểu diễn được trong 32 bit.
// Đặc tả      : docs/giao_tiep_rtl_vi.md, mục 4.1.
//
// Tổng hợp:
//   - Mảng word và hai cổng đọc đồng bộ phù hợp suy luận ROM hai cổng MAX 10.
//   - File hex chứa một word 32 bit little-endian trên mỗi dòng.
// =============================================================================
module soc_rom_dp #(
    parameter integer WORDS = 8192,
    parameter integer USE_INIT_FILE = 0,
    parameter         INIT_FILE = ""
) (
    input  wire        clk_i,
    input  wire        rst_i,

    input  wire        i_req_i,
    input  wire [31:0] i_addr_i,
    output wire        i_gnt_o,
    output wire [31:0] i_rdata_o,
    output wire        i_rvalid_o,
    output wire        i_err_o,

    input  wire        d_req_i,
    input  wire [31:0] d_addr_i,
    output reg  [31:0] d_rdata_o,
    output reg         d_ready_o,
    output reg         d_err_o
);

    localparam [31:0] ROM_BYTES = WORDS * 4;
    function integer clog2;
        input integer value;
        integer temporary;
        begin
            temporary = value - 1;
            for (clog2 = 0; temporary > 0; clog2 = clog2 + 1)
                temporary = temporary >> 1;
        end
    endfunction
    localparam integer ADDR_WIDTH = (WORDS > 1) ? clog2(WORDS) : 1;
    wire [31:0] i_rom_q;
    wire [31:0] d_rom_q;
    reg d_pending_q;
    reg i_valid_q;
    reg i_err_q;
    reg d_pending_err_q;

    wire i_valid_addr = (i_addr_i < ROM_BYTES) && (i_addr_i[1:0] == 2'b00);
    wire d_valid_addr = (d_addr_i < ROM_BYTES) && (d_addr_i[1:0] == 2'b00);

    intel_sync_rom_2p #(
        .WIDTH(32), .WORDS(WORDS), .ADDR_WIDTH(ADDR_WIDTH),
        .USE_INIT_FILE(USE_INIT_FILE), .INIT_FILE(INIT_FILE)
    ) u_storage (
        .clk_i(clk_i),
        .a_en_i(i_req_i && i_gnt_o && i_valid_addr),
        .a_addr_i(i_addr_i[ADDR_WIDTH+1:2]), .a_q_o(i_rom_q),
        .b_en_i(d_req_i && !rst_i && !d_ready_o && !d_pending_q && d_valid_addr),
        .b_addr_i(d_addr_i[ADDR_WIDTH+1:2]), .b_q_o(d_rom_q)
    );

    assign i_gnt_o = !rst_i;
    // Storage đã chốt dữ liệu tại cạnh nhận yêu cầu. Metadata chốt cùng cạnh;
    // bên nhận lấy đáp ứng ở cạnh kế tiếp, không thêm một tầng chốt dữ liệu.
    assign i_rvalid_o = !rst_i && i_valid_q;
    assign i_err_o = i_rvalid_o && i_err_q;
    assign i_rdata_o = (i_rvalid_o && !i_err_q) ? i_rom_q : 32'b0;

    always @(posedge clk_i) begin
        if (rst_i) begin
            i_valid_q <= 1'b0;
            i_err_q <= 1'b0;
            d_rdata_o <= 32'd0;
            d_ready_o <= 1'b0;
            d_err_o   <= 1'b0;
            d_pending_q <= 1'b0;
            d_pending_err_q <= 1'b0;
        end
        else begin
            i_valid_q <= i_req_i && i_gnt_o;
            i_err_q <= i_req_i && i_gnt_o && !i_valid_addr;

            if (d_ready_o) begin
                d_ready_o <= 1'b0;
                d_err_o   <= 1'b0;
            end
            else if (d_pending_q) begin
                d_ready_o <= 1'b1;
                d_err_o   <= d_pending_err_q;
                d_pending_q <= 1'b0;
                if (!d_pending_err_q)
                    d_rdata_o <= d_rom_q;
                else
                    d_rdata_o <= 32'd0;
            end
            else if (d_req_i) begin
                d_pending_q <= 1'b1;
                d_pending_err_q <= !d_valid_addr;
            end
        end
    end

endmodule

`default_nettype wire

rtl\\peripherals\\soc_gpio.v:
`default_nettype none

// =============================================================================
// Module      : soc_gpio
// Chức năng   : GPIO MMIO cho 10 LED và 10 switch của DE10-Lite.
// Thanh ghi   : 0x0 LED_RW, 0x4 SWITCH_RO.
// =============================================================================
module soc_gpio (
    input  wire        clk_i,
    input  wire        rst_i,
    input  wire        req_i,
    input  wire        we_i,
    input  wire [3:0]  addr_i,
    input  wire [31:0] wdata_i,
    input  wire [3:0]  wstrb_i,
    output reg  [31:0] rdata_o,
    output wire        ready_o,
    output reg         err_o,
    input  wire [9:0]  switches_i,
    output wire [9:0]  leds_o
);

    reg [9:0] leds_q;
    assign leds_o  = leds_q;
    assign ready_o = req_i && !rst_i;

    always @* begin
        rdata_o = 32'd0;
        err_o   = 1'b0;
        case (addr_i)
            4'h0: rdata_o = {22'd0, leds_q};
            4'h4: rdata_o = {22'd0, switches_i};
            default: err_o = ready_o;
        endcase
        if (ready_o && we_i && (addr_i != 4'h0))
            err_o = 1'b1;
    end

    always @(posedge clk_i) begin
        if (rst_i)
            leds_q <= 10'd0;
        else if (ready_o && we_i && !err_o) begin
            if (wstrb_i[0]) leds_q[7:0] <= wdata_i[7:0];
            if (wstrb_i[1]) leds_q[9:8] <= wdata_i[9:8];
        end
    end

endmodule

`default_nettype wire

rtl\\peripherals\\soc_i2c_master.v:
`default_nettype none

// =============================================================================
// Module      : soc_i2c_master
// Chức năng   : I2C master theo từng byte, dùng để giao tiếp INA219.
//
// Thanh ghi:
//   0x0 DATA   : byte phát; sau lệnh READ chứa byte nhận. Ghi khi busy phải chờ.
//   0x4 CMD    : bit0 START, bit1 STOP, bit2 READ, bit3 NACK sau READ,
//                bit4 CLEAR_DONE, bit7 EXECUTE. Ghi CMD khi busy tạo wait-state.
//   0x8 STATUS : bit0 busy, bit1 done, bit2 ack_error.
//   0xC DIVIDER: số chu kỳ clock trong nửa chu kỳ SCL (chỉ đọc).
//
// Nguyên tắc điện:
//   scl_drive_low_o/sda_drive_low_o chỉ ra lệnh kéo thấp. Top-level phải nối
//   open-drain: assign pin = drive_low ? 1'b0 : 1'bz. Cần điện trở pull-up.
//   Phiên bản này không hỗ trợ multi-master; clock stretching được tôn trọng
//   bằng cách chỉ lấy mẫu khi chân SCL thực sự đã lên cao.
// =============================================================================
module soc_i2c_master #(
    parameter integer CLOCK_HZ = 50000000,
    parameter integer I2C_HZ   = 100000
) (
    input  wire        clk_i,
    input  wire        rst_i,
    input  wire        req_i,
    input  wire        we_i,
    input  wire [3:0]  addr_i,
    input  wire [31:0] wdata_i,
    input  wire [3:0]  wstrb_i,
    output reg  [31:0] rdata_o,
    output wire        ready_o,
    output wire        err_o,

    input  wire        scl_i,
    input  wire        sda_i,
    output reg         scl_drive_low_o,
    output reg         sda_drive_low_o,
    output wire        busy_o
);

    localparam integer HALF_DIV = (I2C_HZ > 0) ? CLOCK_HZ / (I2C_HZ * 2) : 1;
    localparam integer DIV_WIDTH = (HALF_DIV > 1) ? $clog2(HALF_DIV + 1) : 1;
    localparam integer HALF_RELOAD = HALF_DIV - 1;

    // synthesis translate_off
    initial begin
        if (CLOCK_HZ <= 0 || I2C_HZ <= 0 || HALF_DIV < 2)
            $fatal(1, "soc_i2c_master: CLOCK_HZ must be at least 4 * I2C_HZ");
    end
    // synthesis translate_on

    localparam [3:0]
        ST_IDLE       = 4'd0,
        ST_START_A    = 4'd1,
        ST_START_B    = 4'd2,
        ST_BIT_LOW    = 4'd3,
        ST_BIT_HIGH   = 4'd4,
        ST_ACK_LOW    = 4'd5,
        ST_ACK_HIGH   = 4'd6,
        ST_STOP_A     = 4'd7,
        ST_STOP_B     = 4'd8,
        ST_STOP_C     = 4'd9,
        ST_COMPLETE   = 4'd10,
        ST_START_PRE  = 4'd11;

    reg [3:0] state_q;
    reg [DIV_WIDTH-1:0] divider_q;
    reg [7:0] tx_data_q;
    reg [7:0] rx_data_q;
    reg [2:0] bit_index_q;
    reg command_read_q;
    reg command_stop_q;
    reg command_nack_q;
    reg busy_q;
    reg done_q;
    reg ack_error_q;

    wire valid_addr = (addr_i == 4'h0) || (addr_i == 4'h4) ||
                      (addr_i == 4'h8) || (addr_i == 4'hC);
    wire cmd_write = req_i && we_i && (addr_i == 4'h4) && wstrb_i[0];
    wire data_write = req_i && we_i && (addr_i == 4'h0) && wstrb_i[0];
    wire tick = (divider_q == 0);
    // Count a full high phase AFTER the target releases SCL. Sampling once per
    // divider tick could otherwise shorten a stretched high phase to one clock.
    wire wait_scl = ((state_q == ST_START_A) || (state_q == ST_BIT_HIGH) ||
                     (state_q == ST_ACK_HIGH) || (state_q == ST_STOP_B)) && !scl_i;
    wire wait_bus = (state_q == ST_START_A) && !sda_i;

    assign busy_o = busy_q;
    assign err_o = req_i && !rst_i && (!valid_addr ||
                   (we_i && (addr_i != 4'h0) && (addr_i != 4'h4)));
    assign ready_o = req_i && !rst_i &&
                     (err_o || !((cmd_write || data_write) && busy_q));

    always @* begin
        case (addr_i)
            4'h0: rdata_o = {24'd0, rx_data_q};
            4'h8: rdata_o = {29'd0, ack_error_q, done_q, busy_q};
            4'hC: rdata_o = HALF_DIV;
            default: rdata_o = 32'd0;
        endcase
    end

    always @(posedge clk_i) begin
        if (rst_i) begin
            state_q          <= ST_IDLE;
            divider_q        <= {DIV_WIDTH{1'b0}};
            tx_data_q        <= 8'd0;
            rx_data_q        <= 8'd0;
            bit_index_q      <= 3'd7;
            command_read_q   <= 1'b0;
            command_stop_q   <= 1'b0;
            command_nack_q   <= 1'b1;
            busy_q           <= 1'b0;
            done_q           <= 1'b0;
            ack_error_q      <= 1'b0;
            scl_drive_low_o  <= 1'b0;
            sda_drive_low_o  <= 1'b0;
        end
        else begin
            if (data_write && ready_o && !err_o)
                tx_data_q <= wdata_i[7:0];

            if (cmd_write && ready_o) begin
                if (wdata_i[4])
                    done_q <= 1'b0;
                if (wdata_i[7]) begin
                    command_read_q <= wdata_i[2];
                    command_stop_q <= wdata_i[1];
                    command_nack_q <= wdata_i[3];
                    bit_index_q    <= 3'd7;
                    rx_data_q      <= 8'd0;
                    busy_q         <= 1'b1;
                    done_q         <= 1'b0;
                    ack_error_q    <= 1'b0;
                    divider_q      <= HALF_RELOAD[DIV_WIDTH-1:0];
                    if (wdata_i[0]) begin
                        // Repeated START: release SDA while SCL is still low,
                        // then raise SCL. Never generate a spurious STOP.
                        sda_drive_low_o <= 1'b0;
                        state_q <= scl_drive_low_o ? ST_START_PRE : ST_START_A;
                    end
                    else begin
                        scl_drive_low_o <= 1'b1;
                        sda_drive_low_o <= wdata_i[2] ? 1'b0 : !tx_data_q[7];
                        state_q         <= ST_BIT_LOW;
                    end
                end
            end
            else if (busy_q) begin
                if (wait_scl || wait_bus) begin
                    divider_q <= HALF_DIV[DIV_WIDTH-1:0];
                end
                else if (!tick) begin
                    divider_q <= divider_q - 1'b1;
                end
                else begin
                    divider_q <= HALF_RELOAD[DIV_WIDTH-1:0];
                    case (state_q)
                        ST_START_PRE: begin
                            scl_drive_low_o <= 1'b0;
                            state_q <= ST_START_A;
                        end
                        ST_START_A: begin
                            // Bus rảnh: cả hai đường đã được nhả cao.
                            sda_drive_low_o <= 1'b1;
                            state_q <= ST_START_B;
                        end
                        ST_START_B: begin
                            scl_drive_low_o <= 1'b1;
                            sda_drive_low_o <= command_read_q ? 1'b0 : !tx_data_q[7];
                            state_q <= ST_BIT_LOW;
                        end
                        ST_BIT_LOW: begin
                            scl_drive_low_o <= 1'b0;
                            state_q <= ST_BIT_HIGH;
                        end
                        ST_BIT_HIGH: begin
                            if (scl_i) begin
                                if (command_read_q)
                                    rx_data_q[bit_index_q] <= sda_i;
                                scl_drive_low_o <= 1'b1;
                                if (bit_index_q == 0) begin
                                    sda_drive_low_o <= command_read_q ? !command_nack_q : 1'b0;
                                    state_q <= ST_ACK_LOW;
                                end
                                else begin
                                    bit_index_q <= bit_index_q - 1'b1;
                                    sda_drive_low_o <= command_read_q ? 1'b0 : !tx_data_q[bit_index_q - 1'b1];
                                    state_q <= ST_BIT_LOW;
                                end
                            end
                        end
                        ST_ACK_LOW: begin
                            scl_drive_low_o <= 1'b0;
                            state_q <= ST_ACK_HIGH;
                        end
                        ST_ACK_HIGH: begin
                            // Finish the ninth pulse before accepting the next
                            // byte. A command without STOP retains SCL low.
                            scl_drive_low_o <= 1'b1;
                            if (!command_read_q)
                                ack_error_q <= sda_i;
                            if (command_stop_q) begin
                                scl_drive_low_o <= 1'b1;
                                sda_drive_low_o <= 1'b1;
                                state_q <= ST_STOP_A;
                            end
                            else begin
                                sda_drive_low_o <= 1'b0;
                                state_q <= ST_COMPLETE;
                            end
                        end
                        ST_STOP_A: begin
                            scl_drive_low_o <= 1'b0;
                            state_q <= ST_STOP_B;
                        end
                        ST_STOP_B: begin
                            sda_drive_low_o <= 1'b0;
                            state_q <= ST_STOP_C;
                        end
                        ST_STOP_C: begin
                            state_q <= ST_COMPLETE;
                        end
                        ST_COMPLETE: begin
                            busy_q <= 1'b0;
                            done_q <= 1'b1;
                            state_q <= ST_IDLE;
                            // STOP already released SCL; otherwise keep it low
                            // across software latency between byte commands.
                            sda_drive_low_o <= 1'b0;
                        end
                        default: begin
                            busy_q <= 1'b0;
                            state_q <= ST_IDLE;
                            scl_drive_low_o <= 1'b0;
                            sda_drive_low_o <= 1'b0;
                        end
                    endcase
                end
            end
        end
    end

endmodule

`default_nettype wire

rtl\\peripherals\\soc_timer.v:
`default_nettype none

// =============================================================================
// Module      : soc_timer
// Chức năng   : Bộ đếm thời gian tự do 64 bit và mốc compare 64 bit.
// Thanh ghi   : 0x0 TIME_LO, 0x4 TIME_HI, 0x8 CMP_LO, 0xC CMP_HI.
// Đọc TIME_LO chốt TIME_HI cho lần đọc sau, tránh rách dữ liệu lúc rollover.
// irq_o giữ mức 1 khi time >= compare; compare=all-ones vô hiệu hóa IRQ.
// =============================================================================
module soc_timer (
    input  wire        clk_i,
    input  wire        rst_i,
    input  wire        req_i,
    input  wire        we_i,
    input  wire [3:0]  addr_i,
    input  wire [31:0] wdata_i,
    input  wire [3:0]  wstrb_i,
    output reg  [31:0] rdata_o,
    output wire        ready_o,
    output reg         err_o,
    output wire        irq_o
);

    reg [63:0] time_q;
    reg [63:0] compare_q;
    reg [31:0] snapshot_hi_q;
    reg snapshot_valid_q;
    assign ready_o = req_i && !rst_i;
    assign irq_o   = !rst_i && (compare_q != 64'hFFFF_FFFF_FFFF_FFFF) &&
                     (time_q >= compare_q);

    always @* begin
        err_o = 1'b0;
        case (addr_i)
            4'h0: rdata_o = time_q[31:0];
            4'h4: rdata_o = snapshot_valid_q ? snapshot_hi_q : time_q[63:32];
            4'h8: rdata_o = compare_q[31:0];
            4'hC: rdata_o = compare_q[63:32];
            default: begin rdata_o = 32'd0; err_o = ready_o; end
        endcase
        if (ready_o && we_i && (addr_i != 4'h8) && (addr_i != 4'hC))
            err_o = 1'b1;
    end

    always @(posedge clk_i) begin
        if (rst_i) begin
            time_q    <= 64'd0;
            compare_q <= 64'hFFFF_FFFF_FFFF_FFFF;
            snapshot_hi_q <= 32'd0;
            snapshot_valid_q <= 1'b0;
        end
        else begin
            time_q <= time_q + 64'd1;
            if (ready_o && !we_i && !err_o && (addr_i == 4'h0)) begin
                snapshot_hi_q <= time_q[63:32];
                snapshot_valid_q <= 1'b1;
            end
            if (ready_o && we_i && !err_o) begin
                if (addr_i == 4'h8) begin
                    if (wstrb_i[0]) compare_q[7:0]   <= wdata_i[7:0];
                    if (wstrb_i[1]) compare_q[15:8]  <= wdata_i[15:8];
                    if (wstrb_i[2]) compare_q[23:16] <= wdata_i[23:16];
                    if (wstrb_i[3]) compare_q[31:24] <= wdata_i[31:24];
                end
                if (addr_i == 4'hC) begin
                    if (wstrb_i[0]) compare_q[39:32] <= wdata_i[7:0];
                    if (wstrb_i[1]) compare_q[47:40] <= wdata_i[15:8];
                    if (wstrb_i[2]) compare_q[55:48] <= wdata_i[23:16];
                    if (wstrb_i[3]) compare_q[63:56] <= wdata_i[31:24];
                end
            end
        end
    end

endmodule

`default_nettype wire

rtl\\peripherals\\soc_uart_tx.v:
`default_nettype none

// =============================================================================
// Module      : soc_uart_tx
// Chức năng   : UART truyền 8N1 tối giản, phù hợp log SOC ra máy tính.
//
// Thanh ghi:
//   0x0 DATA   : ghi byte để truyền; bus tự wait-state khi bộ phát đang bận.
//   0x4 STATUS : bit 0 tx_ready, bit 1 tx_busy.
//
// Không có FIFO để giữ RTL nhỏ và hành vi xác định. Firmware phải kiểm tra
// STATUS hoặc đơn giản ghi DATA: giao tiếp ready sẽ giữ pipeline đến khi rảnh.
// =============================================================================
module soc_uart_tx #(
    parameter integer CLOCK_HZ = 50000000,
    parameter integer BAUD     = 115200
) (
    input  wire        clk_i,
    input  wire        rst_i,
    input  wire        req_i,
    input  wire        we_i,
    input  wire [3:0]  addr_i,
    input  wire [31:0] wdata_i,
    input  wire [3:0]  wstrb_i,
    output reg  [31:0] rdata_o,
    output wire        ready_o,
    output wire        err_o,
    output wire        tx_o,
    output wire        busy_o
);

    localparam integer BAUD_DIV = (BAUD > 0) ? (CLOCK_HZ + (BAUD/2)) / BAUD : 1;
    localparam integer DIV_WIDTH = (BAUD_DIV > 1) ? $clog2(BAUD_DIV) : 1;
    localparam integer BAUD_RELOAD = BAUD_DIV - 1;

    // synthesis translate_off
    initial begin
        if (CLOCK_HZ <= 0 || BAUD <= 0 || BAUD_DIV < 1)
            $fatal(1, "soc_uart_tx: invalid CLOCK_HZ/BAUD");
    end
    // synthesis translate_on

    reg [9:0] tx_shift_q;
    reg [3:0] bit_count_q;
    reg [DIV_WIDTH-1:0] baud_count_q;
    reg busy_q;

    wire valid_addr = (addr_i == 4'h0) || (addr_i == 4'h4);
    wire data_write = req_i && we_i && (addr_i == 4'h0) && wstrb_i[0];

    assign busy_o  = busy_q;
    assign tx_o    = busy_q ? tx_shift_q[0] : 1'b1;
    assign err_o   = req_i && !rst_i && (!valid_addr || (we_i && (addr_i != 4'h0)));
    assign ready_o = req_i && !rst_i && (err_o || !(data_write && busy_q));

    always @* begin
        case (addr_i)
            4'h4: rdata_o = {30'd0, busy_q, !busy_q};
            default: rdata_o = 32'd0;
        endcase
    end

    always @(posedge clk_i) begin
        if (rst_i) begin
            tx_shift_q   <= 10'h3FF;
            bit_count_q  <= 4'd0;
            baud_count_q <= {DIV_WIDTH{1'b0}};
            busy_q       <= 1'b0;
        end
        else begin
            if (data_write && ready_o) begin
                // LSB phát trước: start(0), 8 data bit, stop(1).
                tx_shift_q   <= {1'b1, wdata_i[7:0], 1'b0};
                bit_count_q  <= 4'd10;
                baud_count_q <= BAUD_RELOAD[DIV_WIDTH-1:0];
                busy_q       <= 1'b1;
            end
            else if (busy_q) begin
                if (baud_count_q == 0) begin
                    tx_shift_q   <= {1'b1, tx_shift_q[9:1]};
                    baud_count_q <= BAUD_RELOAD[DIV_WIDTH-1:0];
                    if (bit_count_q == 1) begin
                        bit_count_q <= 4'd0;
                        busy_q      <= 1'b0;
                    end
                    else begin
                        bit_count_q <= bit_count_q - 4'd1;
                    end
                end
                else begin
                    baud_count_q <= baud_count_q - 1'b1;
                end
            end
        end
    end

endmodule

`default_nettype wire

rtl\\soc\\rv32_soc.v:
`default_nettype none

`include "soc_map.vh"

// =============================================================================
// Module      : rv32_soc
// Chức năng   : SoC 32 bit cho bài toán ước lượng SOC pin trên DE10-Lite.
//
// Thành phần:
//   - rv32_core: RV32I pipeline 5 tầng, Harvard, có wait-state và precise trap.
//   - ROM 32 KiB hai cổng, SRAM 8 KiB.
//   - GPIO, UART TX, I2C master, timer 64 bit và QNN accelerator 80-16-8-1.
//
// Memory map:
//   0x0000_0000..0x0000_7FFF : ROM 32 KiB, execute/read-only
//   0x1000_0000..0x1000_1FFF : SRAM
//   0x2000_0000..0x2000_000F : GPIO
//   0x2000_1000..0x2000_100F : UART TX
//   0x2000_2000..0x2000_200F : I2C master
//   0x2000_3000..0x2000_3FFF : QNN accelerator
//   0x2000_4000..0x2000_400F : timer
//
// Bus dữ liệu trả ready+err ngay cho địa chỉ không ánh xạ và ghi ROM.
// Cổng lấy lệnh nối thẳng ROM, nhận req/gnt và trả rvalid sau một chu kỳ.
// Core và các slave cùng clock/reset. Các chân bất đồng bộ phải được đồng bộ
// ở lớp board. Đặc tả giao tiếp: docs/giao_tiep_rtl_vi.md.
// =============================================================================
module rv32_soc #(
    parameter integer CLOCK_HZ = 50000000,
    parameter integer ROM_WORDS = 8192,
    parameter integer RAM_WORDS = 2048,
    parameter integer USE_ROM_INIT_FILE = 0,
    parameter         ROM_INIT_FILE = "",
    parameter integer USE_QNN_INIT_FILES = 0,
    parameter integer QNN_L1_SHIFT = 0,
    parameter integer QNN_L2_SHIFT = 0,
    parameter integer QNN_OUT_SHIFT = 0,
    parameter         QNN_L1_WEIGHT_FILE = "",
    parameter         QNN_L1_BIAS_FILE = "",
    parameter         QNN_L2_WEIGHT_FILE = "",
    parameter         QNN_L2_BIAS_FILE = "",
    parameter         QNN_OUT_WEIGHT_FILE = "",
    parameter         QNN_OUT_BIAS_FILE = ""
) (
    // Clock/reset: shared by core, decoder and all slaves.
    input  wire       clk_i,
    input  wire       rst_i,

    // Board I/O: inputs must already be synchronized by the board wrapper.
    input  wire [9:0] switches_i,
    output wire [9:0] leds_o,
    output wire       uart_tx_o,

    // Open-drain I2C: 1 on drive_low requests pulling the pad low.
    input  wire       i2c_scl_i,
    input  wire       i2c_sda_i,
    output wire       i2c_scl_drive_low_o,
    output wire       i2c_sda_drive_low_o,

    // Latched CPU fault status.
    output wire       halted_o,
    output wire       trap_valid_o,
    output wire [4:0] trap_cause_o,
    output wire [31:0] trap_pc_o,

    // Accelerator status.
    output wire       qnn_busy_o,
    output wire       qnn_done_o,
    output wire [31:0] qnn_result_o
);

    // Instruction channel: core <-> ROM (request/grant, then response).
    wire        imem_req;
    wire [31:0] imem_addr;
    wire        imem_gnt;
    wire        imem_rvalid;
    wire [31:0] imem_rdata;
    wire        imem_err;

    // Data channel: core <-> decoder (hold request until ready).
    wire        dmem_req;
    wire        dmem_we;
    wire [31:0] dmem_addr;
    wire [31:0] dmem_wdata;
    wire [3:0]  dmem_wstrb;
    wire [31:0] dmem_rdata;
    wire        dmem_ready;
    wire        dmem_err;

    // Each slave connects its request and response to the same named lane.
    wire [`SOC_SLAVE_COUNT-1:0]    slave_req;
    wire [`SOC_SLAVE_COUNT*32-1:0] slave_rdata;
    wire [`SOC_SLAVE_COUNT-1:0]    slave_ready;
    wire [`SOC_SLAVE_COUNT-1:0]    slave_err;

    // 1. CPU master
    rv32_core #(
        .RESET_VECTOR(`SOC_ROM_BASE)
    ) u_core (
        .clk_i(clk_i),
        .rst_i(rst_i),
        .imem_req_o(imem_req),
        .imem_addr_o(imem_addr),
        .imem_gnt_i(imem_gnt),
        .imem_rvalid_i(imem_rvalid),
        .imem_rdata_i(imem_rdata),
        .imem_err_i(imem_err),
        .dmem_req_o(dmem_req),
        .dmem_we_o(dmem_we),
        .dmem_addr_o(dmem_addr),
        .dmem_wdata_o(dmem_wdata),
        .dmem_wstrb_o(dmem_wstrb),
        .dmem_rdata_i(dmem_rdata),
        .dmem_ready_i(dmem_ready),
        .dmem_err_i(dmem_err),
        .halted_o(halted_o),
        .trap_valid_o(trap_valid_o),
        .trap_cause_o(trap_cause_o),
        .trap_pc_o(trap_pc_o),
        .trap_instr_o(),
        .retire_valid_o(),
        .retire_pc_o(),
        .retire_instr_o(),
        .retire_rd_we_o(),
        .retire_rd_addr_o(),
        .retire_rd_data_o(),
        .debug_fetch_pc_o()
    );

    // 2. Data decoder: one selected request, one matching response.
    soc_bus #(
        .ROM_WORDS(ROM_WORDS),
        .RAM_WORDS(RAM_WORDS)
    ) u_bus (
        .rst_i(rst_i),
        .req_i(dmem_req),
        .we_i(dmem_we),
        .addr_i(dmem_addr),
        .rdata_o(dmem_rdata),
        .ready_o(dmem_ready),
        .err_o(dmem_err),
        .slave_req_o(slave_req),
        .slave_rdata_i(slave_rdata),
        .slave_ready_i(slave_ready),
        .slave_err_i(slave_err)
    );

    // 3. Memories: instruction ROM port bypasses the data decoder.
    soc_rom_dp #(
        .WORDS(ROM_WORDS),
        .USE_INIT_FILE(USE_ROM_INIT_FILE),
        .INIT_FILE(ROM_INIT_FILE)
    ) u_rom (
        .clk_i(clk_i),
        .rst_i(rst_i),
        .i_req_i(imem_req),
        .i_addr_i(imem_addr),
        .i_gnt_o(imem_gnt),
        .i_rvalid_o(imem_rvalid),
        .i_rdata_o(imem_rdata),
        .i_err_o(imem_err),
        .d_req_i(slave_req[`SOC_SLAVE_ROM]),
        .d_addr_i(dmem_addr),
        .d_rdata_o(slave_rdata[`SOC_SLAVE_ROM*32 +: 32]),
        .d_ready_o(slave_ready[`SOC_SLAVE_ROM]),
        .d_err_o(slave_err[`SOC_SLAVE_ROM])
    );

    soc_ram #(.WORDS(RAM_WORDS)) u_ram (
        .clk_i(clk_i),
        .rst_i(rst_i),
        .req_i(slave_req[`SOC_SLAVE_RAM]),
        .we_i(dmem_we),
        .addr_i(dmem_addr - `SOC_RAM_BASE),
        .wdata_i(dmem_wdata),
        .wstrb_i(dmem_wstrb),
        .rdata_o(slave_rdata[`SOC_SLAVE_RAM*32 +: 32]),
        .ready_o(slave_ready[`SOC_SLAVE_RAM]),
        .err_o(slave_err[`SOC_SLAVE_RAM])
    );

    // 4. MMIO slaves, in lane order. Address inputs are local byte offsets.
    soc_gpio u_gpio (
        .clk_i(clk_i),
        .rst_i(rst_i),
        .req_i(slave_req[`SOC_SLAVE_GPIO]),
        .we_i(dmem_we),
        .addr_i(dmem_addr[3:0]),
        .wdata_i(dmem_wdata),
        .wstrb_i(dmem_wstrb),
        .rdata_o(slave_rdata[`SOC_SLAVE_GPIO*32 +: 32]),
        .ready_o(slave_ready[`SOC_SLAVE_GPIO]),
        .err_o(slave_err[`SOC_SLAVE_GPIO]),
        .switches_i(switches_i),
        .leds_o(leds_o)
    );

    soc_uart_tx #(
        .CLOCK_HZ(CLOCK_HZ),
        .BAUD(115200)
    ) u_uart (
        .clk_i(clk_i),
        .rst_i(rst_i),
        .req_i(slave_req[`SOC_SLAVE_UART]),
        .we_i(dmem_we),
        .addr_i(dmem_addr[3:0]),
        .wdata_i(dmem_wdata),
        .wstrb_i(dmem_wstrb),
        .rdata_o(slave_rdata[`SOC_SLAVE_UART*32 +: 32]),
        .ready_o(slave_ready[`SOC_SLAVE_UART]),
        .err_o(slave_err[`SOC_SLAVE_UART]),
        .tx_o(uart_tx_o),
        .busy_o()
    );

    soc_i2c_master #(
        .CLOCK_HZ(CLOCK_HZ),
        .I2C_HZ(100000)
    ) u_i2c (
        .clk_i(clk_i),
        .rst_i(rst_i),
        .req_i(slave_req[`SOC_SLAVE_I2C]),
        .we_i(dmem_we),
        .addr_i(dmem_addr[3:0]),
        .wdata_i(dmem_wdata),
        .wstrb_i(dmem_wstrb),
        .rdata_o(slave_rdata[`SOC_SLAVE_I2C*32 +: 32]),
        .ready_o(slave_ready[`SOC_SLAVE_I2C]),
        .err_o(slave_err[`SOC_SLAVE_I2C]),
        .scl_i(i2c_scl_i),
        .sda_i(i2c_sda_i),
        .scl_drive_low_o(i2c_scl_drive_low_o),
        .sda_drive_low_o(i2c_sda_drive_low_o),
        .busy_o()
    );

    qnn_soc_accelerator #(
        .USE_INIT_FILES(USE_QNN_INIT_FILES),
        .L1_SHIFT(QNN_L1_SHIFT),
        .L2_SHIFT(QNN_L2_SHIFT),
        .OUT_SHIFT(QNN_OUT_SHIFT),
        .L1_WEIGHT_FILE(QNN_L1_WEIGHT_FILE),
        .L1_BIAS_FILE(QNN_L1_BIAS_FILE),
        .L2_WEIGHT_FILE(QNN_L2_WEIGHT_FILE),
        .L2_BIAS_FILE(QNN_L2_BIAS_FILE),
        .OUT_WEIGHT_FILE(QNN_OUT_WEIGHT_FILE),
        .OUT_BIAS_FILE(QNN_OUT_BIAS_FILE)
    ) u_qnn (
        .clk_i(clk_i),
        .rst_i(rst_i),
        .bus_req_i(slave_req[`SOC_SLAVE_QNN]),
        .bus_we_i(dmem_we),
        .bus_addr_i(dmem_addr[11:0]),
        .bus_wdata_i(dmem_wdata),
        .bus_wstrb_i(dmem_wstrb),
        .bus_rdata_o(slave_rdata[`SOC_SLAVE_QNN*32 +: 32]),
        .bus_ready_o(slave_ready[`SOC_SLAVE_QNN]),
        .bus_err_o(slave_err[`SOC_SLAVE_QNN]),
        .busy_o(qnn_busy_o),
        .done_o(qnn_done_o),
        .result_o(qnn_result_o)
    );

    soc_timer u_timer (
        .clk_i(clk_i),
        .rst_i(rst_i),
        .req_i(slave_req[`SOC_SLAVE_TIMER]),
        .we_i(dmem_we),
        .addr_i(dmem_addr[3:0]),
        .wdata_i(dmem_wdata),
        .wstrb_i(dmem_wstrb),
        .rdata_o(slave_rdata[`SOC_SLAVE_TIMER*32 +: 32]),
        .ready_o(slave_ready[`SOC_SLAVE_TIMER]),
        .err_o(slave_err[`SOC_SLAVE_TIMER]),
        .irq_o()
    );

endmodule

`default_nettype wire
